35	/// Dialogue module demo. A very basic top-down scene drawn entirely with generated meshes:
36	/// walk the player blob around a grass field with WASD, approach the cow NPC at the top-left,
37	/// and press E to start a Yarn conversation. The line text wraps and reveals
38	/// character-by-character; pick a reply with the up/down arrows and E. Yarn
39	/// <c>&lt;&lt;emote who kind&gt;&gt;</c> commands show the speaker's framed mesh portrait inside
40	/// the box and <c>&lt;&lt;react who mark&gt;&gt;</c> pops a mesh reaction mark above a head.
41	///
42	/// Showcases the dialogue module (<see cref="DialogueSystem"/> + Yarn runtime, fed an
43	/// in-memory-compiled program so the demo ships no .yarn asset) in its mesh-chrome mode, the
44	/// rendering-text reveal, and procedural mesh rendering on the Main/UI targets.
45	public class DialogueDemoScreen : IGameScreen
46	{
47	    private const float BoundaryHalfWidth = 380f;
48	    private const float BoundaryHalfHeight = 220f;
49	    private const float PlayerSpeed = 135f;       // 0.75× the original
50	    private const float PlayerBodyRadius = 30f;   // mesh player: body radius (feet at the transform)
51	    private const float CowBodyRadius = 42f;      // mesh cow: a little larger than the player
52	    private const float InteractRange = 170f;
53	    private const float ReactionDuration = 1.6f;  // above-head reaction marks auto-hide
54	    private const float ReactionMarkSize = 36f;   // above-head mesh glyph size
55	
56	    // Dialogue-box tuning passed into DialogueSystem. The box is now generated meshes
57	    // (white outline, black fill) with a left gutter holding a framed emote glyph.
58	    private const float DialogueTextScale = 0.27f;
59	    private const float DialogueIndicatorSize = 40f;
60	    private const float DialogueBoxHeight = 150f;
61	    private const float DialoguePortraitGutter = 140f; // left reserve inside the box for the emote frame
62	    private const float DialogueBalloonPadding = 14f;
63	
64	    // The in-box emote portrait: a mesh frame (white outline, black fill) with the speaker's
65	    // mesh face glyph centred inside it.
66	    private const float FrameRenderSize = 116f;   // the square emote frame
67	    private const float FaceRenderSize = 84f;     // speaker face glyph, centred in the frame
68	
69	    private static readonly Vector2 PlayerSpawn = new(40f, 90f);
70	    // Upper-left, but low enough that the above-head "E to talk" prompt clears the header banner.
71	    private static readonly Vector2 NpcPosition = new(-300f, -60f);
72	
73	    private readonly ContentManager _content;
74	    private readonly GraphicsDevice _graphicsDevice;
75	    private readonly MonoDreams.Component.Camera _camera;
76	    private readonly ViewportManager _viewportManager;
