78	    private readonly World _world;
79	    private readonly Dictionary<RenderTargetID, RenderTarget2D> _renderTargets;
80	    private readonly BitmapFont _font;
81	
82	    // Shared per-action input. The SAME interact instance feeds both the NPC trigger and
83	    // DialogueSystem, so DialogueSystem.StartYarnDialogue's _interact.Consume() stops the
84	    // opening E press from also advancing the first line.
85	    private readonly DemoInputState _interact = new();
86	    private readonly DemoInputState _up = new();
87	    private readonly DemoInputState _down = new();
