98	    public DialogueDemoScreen(GraphicsDevice graphicsDevice, ContentManager content,
99	        MonoDreams.Component.Camera camera, ViewportManager viewportManager, SpriteBatch spriteBatch)
100	    {
101	        _graphicsDevice = graphicsDevice;
102	        _content = content;
103	        _camera = camera;
104	        _viewportManager = viewportManager;
105	        _spriteBatch = spriteBatch;
106	        _renderTargets = new Dictionary<RenderTargetID, RenderTarget2D>
107	        {
108	            { RenderTargetID.Main, new RenderTarget2D(graphicsDevice, viewportManager.VirtualWidth, viewportManager.VirtualHeight) },
109	            { RenderTargetID.UI, new RenderTarget2D(graphicsDevice, viewportManager.VirtualWidth, viewportManager.VirtualHeight) },
110	            { RenderTargetID.HUD, new RenderTarget2D(graphicsDevice, viewportManager.VirtualWidth, viewportManager.VirtualHeight) },
111	        };
112	        _font = content.Load<BitmapFont>("Fonts/UAV-OSD-Sans-Mono-72-White-fnt");
113	
114	        camera.Position = Vector2.Zero;
115	
116	        _world = new World();
117	        // Pipelines are built in Load — DialogueSystem needs textures from `content`.
118	    }
