120	    public void Load(ScreenController screenController, ContentManager content)
121	    {
122	        _screenController = screenController;
123	        _world.Subscribe<DemoButtonClicked>(OnButtonClicked);
124	        _world.Subscribe<DialogueActiveMessage>(OnDialogueActive);
125	
126	        MonoDreams.Cursor.Cursor.CreateMesh(_world,
127	            ShapeBuilder.Arrow(26f, Color.Black, Color.White).Generate(), RenderTargetID.HUD);
128	
129	        CreateGround();
130	        CreateBoundary();
131	        var playerMark = CreatePlayer();
132	        var (npcMark, prompt) = CreateNpc();
133	
134	        // Box / balloon / indicator are generated meshes (white outline, black fill).
135	        var dialogueSystem = new DialogueSystem(
136	            _world,
137	            dialogBoxTexture: null,
138	            _font,
139	            indicatorTexture: null,
140	            _viewportManager.VirtualWidth, _viewportManager.VirtualHeight,
141	            layerDepth: 0.9f,
142	            _interact, _up, _down,
143	            new[] { CompileYarn(YarnSource) },
144	            textScale: DialogueTextScale,
145	            indicatorSize: DialogueIndicatorSize,
146	            portraitGutter: DialoguePortraitGutter,
147	            balloonPadding: DialogueBalloonPadding,
148	            boxHeight: DialogueBoxHeight,
149	            chromeFill: Color.Black,
150	            chromeOutline: Color.White,
151	            chromeThickness: 2f,
152	            indicatorColor: Color.White);
153	
154	        // A single emote frame in the box's left gutter shows whoever is speaking.
155	        var portrait = CreatePortraitSlot(dialogueSystem.PortraitGutterBounds);
156	
157	        BuildHud(content);
158	
159	        // <<react who mark>> → above-head mesh mark; <<emote who kind>> → the in-box portrait
160	        // (cow face for the NPC, emote face glyph for the player). Both arrive as DialogueCommandMessage.
161	        var reactionSystem = new ReactionMarkSystem(_world, playerMark, npcMark, ReactionDuration, ReactionMarkSize);
162	        var portraitSystem = new DialoguePortraitSystem(_world, portrait, FrameRenderSize, FaceRenderSize);
163	
164	        UpdateSystem = CreateUpdateSystem(dialogueSystem, prompt, reactionSystem, portraitSystem);
165	        DrawSystem = CreateDrawSystem();
166	    }
