170	    /// The grass field: a filled green rectangle covering the boundary, with a faint grid
171	    /// of lines for texture. Replaces the old grass tile sprites.
172	    private void CreateGround()
173	    {
174	        var field = new Rectangle(
175	            -(int)BoundaryHalfWidth, -(int)BoundaryHalfHeight,
176	            (int)BoundaryHalfWidth * 2, (int)BoundaryHalfHeight * 2);
177	        ShapeBuilder.Filled(_world, field, new Color(58, 92, 64), RenderTargetID.Main, depth: 0.08f);
178	
179	        // Faint grid lines so the field reads as ground rather than a flat block.
180	        const float step = 80f;
181	        var grid = new CompositeMeshGenerator();
182	        var lineColor = new Color(72, 110, 78);
183	        for (var x = field.Left + (int)step; x < field.Right; x += (int)step)
184	            grid.Add(new LineMeshGenerator(new Vector2(x, field.Top), new Vector2(x, field.Bottom), 1f, lineColor));
185	        for (var y = field.Top + (int)step; y < field.Bottom; y += (int)step)
186	            grid.Add(new LineMeshGenerator(new Vector2(field.Left, y), new Vector2(field.Right, y), 1f, lineColor));
187	        ShapeBuilder.Create(_world, grid, RenderTargetID.Main, depth: 0.09f);
188	    }
189	
190	    private void CreateBoundary()
191	    {
192	        var bounds = new Rectangle(
193	            -(int)BoundaryHalfWidth, -(int)BoundaryHalfHeight,
194	            (int)BoundaryHalfWidth * 2, (int)BoundaryHalfHeight * 2);
195	
196	        var boundary = _world.CreateEntity();
197	        boundary.Set(new TransformComponent(Vector2.Zero));
198	        var draw = new DrawComponent { Target = RenderTargetID.Main, LayerDepth = 0.2f };
199	        draw.SetMeshData(new RectangleOutlineMeshGenerator(bounds, thickness: 2f, color: DemoPalette.TextLight));
200	        boundary.Set(draw);
201	        boundary.Set<VisibleComponent>();
202	    }
