204	    /// Returns the player's above-head reaction-mark child (hidden until a `<<react>>` command).
205	    private Entity CreatePlayer()
206	    {
207	        _player = _world.CreateEntity();
208	        _player.Set(new EntityInfoComponent("Player", "DialogueDemoPlayer"));
209	        _player.Set(new TransformComponent(PlayerSpawn));
210	        _player.Set(new PlayerTag());
211	        var draw = new DrawComponent { Target = RenderTargetID.Main, LayerDepth = 0.50f };
212	        draw.SetMeshData(DialogueGlyphs.PlayerShape(PlayerBodyRadius));
213	        _player.Set(draw);
214	        _player.Set<VisibleComponent>();
215	
216	        return CreateReactionChild(_player, new Vector2(0, -2f * PlayerBodyRadius - 20f));
217	    }
218	
219	    /// Returns (cow's reaction-mark child, "E to talk" prompt child).
220	    private (Entity mark, Entity prompt) CreateNpc()
221	    {
222	        _npc = _world.CreateEntity();
223	        _npc.Set(new EntityInfoComponent("NPC", "DialogueDemoCow"));
224	        _npc.Set(new TransformComponent(NpcPosition));
225	        var draw = new DrawComponent { Target = RenderTargetID.Main, LayerDepth = 0.50f };
226	        draw.SetMeshData(DialogueGlyphs.CowShape(CowBodyRadius));
227	        _npc.Set(draw);
228	        _npc.Set<VisibleComponent>();
229	
230	        var mark = CreateReactionChild(_npc, new Vector2(0, -2f * CowBodyRadius - 18f));
231	
232	        // "E to talk" prompt centred just above the cow's head — shown only when in range.
233	        const float promptScale = 0.26f;
234	        const string promptText = "E to talk";
235	        var measured = _font.MeasureString(promptText);
236	        var prompt = _world.CreateEntity();
237	        prompt.Set(new EntityInfoComponent("DialogueDemo", "InteractPrompt"));
238	        prompt.Set(new TransformComponent(new Vector2(-measured.Width * promptScale / 2f, -2f * CowBodyRadius - 30f)));
239	        prompt.SetParent(_npc);
240	        prompt.Set(new DynamicTextComponent
241	        {
242	            Target = RenderTargetID.Main,
243	            LayerDepth = 0.63f,
244	            TextContent = promptText,
245	            Font = _font,
246	            Color = DemoPalette.TextSelected,
247	            Scale = promptScale,
248	            IsRevealed = true,
249	            VisibleCharacterCount = int.MaxValue,
250	        });
251	        prompt.Set(new DrawComponent { Type = DrawElementType.Text, Target = RenderTargetID.Main });
252	        // No VisibleComponent yet — NpcInteractionSystem toggles it.
253	
254	        return (mark, prompt);
255	    }
256	
257	    /// An above-head reaction-mark mesh, child of a character on the Main target. Starts with an
258	    /// empty mesh and no `VisibleComponent`; `ReactionMarkSystem` fills the glyph and toggles the
259	    /// tag (Main respects culling/visibility, so the tag controls it here).
260	    private Entity CreateReactionChild(Entity parent, Vector2 localOffset)
261	    {
262	        var mark = _world.CreateEntity();
263	        mark.Set(new EntityInfoComponent("DialogueDemo", "Reaction"));
264	        mark.Set(new TransformComponent(localOffset));
265	        mark.SetParent(parent);
266	        mark.Set(new DrawComponent { Type = DrawElementType.Mesh, Target = RenderTargetID.Main, LayerDepth = 0.62f });
267	        // No VisibleComponent yet — ReactionMarkSystem toggles it on a <<react>> command.
268	        return mark;
269	    }
270	
271	    /// Creates the single in-box emote portrait — a mesh frame (white outline, black fill) with
272	    /// the speaker's mesh face glyph inside — centred in the dialogue box's left gutter (see
273	    /// DialogueSystem.PortraitGutterBounds). Both start with empty meshes; DialoguePortraitSystem
274	    /// fills them on an &lt;&lt;emote&gt;&gt; command and empties them on dialogue end.
275	    private PortraitSlot CreatePortraitSlot(Rectangle gutter)
276	    {
277	        var frameTopLeft = new Vector2(
278	            gutter.X + (gutter.Width - FrameRenderSize) / 2f,
279	            gutter.Y + (gutter.Height - FrameRenderSize) / 2f);
280	        var faceOffset = (FrameRenderSize - FaceRenderSize) / 2f;
281	
282	        // Frame — a mesh panel on UI, empty until the first <<emote>>; VisibleComponent kept on so
283	        // MeshPrepSystem keeps its matrix fresh (UI renders regardless of the tag).
284	        var frame = _world.CreateEntity();
285	        frame.Set(new EntityInfoComponent("DialogueDemo", "PortraitFrame"));
286	        frame.Set(new TransformComponent(frameTopLeft));
287	        frame.Set(new DrawComponent { Type = DrawElementType.Mesh, Target = RenderTargetID.UI, LayerDepth = 0.92f });
288	        frame.Set<VisibleComponent>();
289	
290	        // Speaker face — a mesh glyph on UI, drawn on top of the frame window.
291	        var face = _world.CreateEntity();
292	        face.Set(new EntityInfoComponent("DialogueDemo", "PortraitFace"));
293	        face.Set(new TransformComponent(frameTopLeft + new Vector2(faceOffset, faceOffset)));
294	        face.Set(new DrawComponent { Type = DrawElementType.Mesh, Target = RenderTargetID.UI, LayerDepth = 0.93f });
295	        face.Set<VisibleComponent>();
296	
297	        return new PortraitSlot(frame, face);
298	    }
