321	            CapPixels = 42,
322	            CapLabelScale = 0.22f,
323	        };
324	        var rowStyle = new KeyRowStyle
325	        {
326	            LabelColor = DemoPalette.TextLight,
327	            HoverColor = DemoPalette.TextHover,
328	            ActiveColor = DemoPalette.TextSelected,
329	            LabelScale = 0.18f,
330	            Gap = 10f,
331	            BackgroundColor = DemoPalette.DarkBgSecondary,
332	            HoverBackgroundColor = DemoPalette.DarkBgSecondary,
333	            ActiveBackgroundColor = DemoPalette.DarkBgSecondary,
334	            BackgroundPaddingX = 10f,
