383	    private SequentialSystem<GameState> CreateUpdateSystem(
384	        DialogueSystem dialogueSystem, Entity prompt,
385	        ReactionMarkSystem reactionSystem, DialoguePortraitSystem portraitSystem)
386	    {
387	        return new SequentialSystem<GameState>(
388	            new DialogueDemoInputSystem(_interact, _up, _down),  // feed interact/up/down each frame
389	            new CursorInputSystem(_world),
390	            new IntrinsicSizingSystem(_world),
391	            new AutoLayoutSystem(_world, _viewportManager),
392	            new DemoButtonInteractionSystem(_world),
393	            new PlayerMovementSystem(_world, BoundaryHalfWidth, BoundaryHalfHeight, PlayerSpeed,
394	                PlayerBodyRadius, 2f * PlayerBodyRadius, () => _dialogueActive),
395	            new NpcInteractionSystem(_world, _player, _npc, prompt, _interact, InteractRange, () => _dialogueActive),
396	            dialogueSystem,
397	            reactionSystem,
398	            portraitSystem,
399	            new TextUpdateSystem(_world),                        // advance the reveal animation
400	            new DialogueDemoShortcutSystem(this),
401	            new HierarchySystem(_world),
402	            new CursorPositionSystem(_world, _camera, _viewportManager));
403	    }
