406	    {
407	        return new SequentialSystem<GameState>(
408	            new SpritePrepSystem(_world, _graphicsDevice, pixelPerfectRendering: false),
409	            new TextPrepSystem(_world, pixelPerfectRendering: false),
410	            new MeshPrepSystem(_world),
411	            new ButtonMeshPrepSystem(_world),
412	            new MasterRenderSystem(_spriteBatch, _graphicsDevice, _world,
413	                RenderTargetID.Main, _renderTargets[RenderTargetID.Main], _camera),
414	            new MasterRenderSystem(_spriteBatch, _graphicsDevice, _world,
415	                RenderTargetID.UI, _renderTargets[RenderTargetID.UI]),
416	            new MasterRenderSystem(_spriteBatch, _graphicsDevice, _world,
417	                RenderTargetID.HUD, _renderTargets[RenderTargetID.HUD]),
418	            new FinalDrawSystem(_spriteBatch, _graphicsDevice, _viewportManager, new[]
419	            {
420	                RenderLayer.Main(_renderTargets[RenderTargetID.Main]),
421	                RenderLayer.UI(_renderTargets[RenderTargetID.UI]),
422	                RenderLayer.HUD(_renderTargets[RenderTargetID.HUD]),
423	            }));
424	    }
