436	    // ─── in-memory Yarn ──────────────────────────────────────────────────────
437	
438	    /// The conversation. Lines use Yarn's "Speaker: text" form (DialogueSystem splits the
439	    /// speaker off). `<<emote who kind>>` drives the in-box portrait (left = NPC, right =
440	    /// player); `<<react who mark>>` pops an above-head reaction mark. Both arrive as a
441	    /// DialogueCommandMessage. The start node must be named "Start" (see NpcInteractionSystem).
442	    private const string YarnSource = @"title: Start
443	---
444	<<emote npc happy>>
445	Cow: Moo! A visitor! We don't get many folks wandering out to my little meadow.
446	Cow: What brings you all the way out here, friend?
447	<<emote player question>>
448	-> I'm just exploring the area.
449	    <<emote npc happy>>
450	    Cow: Exploring! Wonderful. There's no finer patch of grass this side of the river.
451	    <<emote player happy>>
452	    <<react player star>>
453	    Player: It really is peaceful out here.
454	-> Do you ever get lonely?
455	    <<emote npc sad>>
456	    Cow: ...Sometimes. The days are long and the field is wide.
457	    <<emote npc happy>>
458	    <<react npc star>>
459	    Cow: But a good chat like this one? That keeps me going.
460	-> Wait, can cows really talk?
461	    <<emote player surprised>>
462	    <<react player question>>
463	    Player: Wait... can cows actually talk?
464	    <<emote npc surprised>>
465	    <<react npc exclaim>>
466	    Cow: Can't yours?
467	    <<emote player surprised>>
468	    Player: ...Fair enough.
469	<<emote npc happy>>
470	Cow: Do come visit again. The meadow's always right here.
471	<<react npc star>>
472	===
473	";
474	
475	    /// Compiles a Yarn source string into a runtime <see cref="YarnProgram"/>, mirroring
476	    /// what <c>YarnSpinnerProcessor</c> does at content-build time — so the demo ships no
477	    /// .yarn asset. The required deps (Yarn.Compiler, Google.Protobuf, CsvHelper) flow in
478	    /// transitively from MonoDreams.
479	    private static YarnProgram CompileYarn(string source)
480	    {
481	        var job = CompilationJob.CreateFromString("DemoDialogue", source);
482	        var result = Compiler.Compile(job);
483	        if (result.Program == null)
484	            throw new InvalidOperationException(
485	                "Demo Yarn script failed to compile: " + string.Join("; ", result.Diagnostics));
486	
487	        var program = new YarnProgram();
488	
489	        using (var memoryStream = new MemoryStream())
490	        using (var outputStream = new CodedOutputStream(memoryStream))
491	        {
492	            result.Program.WriteTo(outputStream);
493	            outputStream.Flush();
494	            program.CompiledProgram = memoryStream.ToArray();
495	        }
496	
497	        using (var memoryStream = new MemoryStream())
498	        {
499	            using var textWriter = new StreamWriter(memoryStream);
500	            var csv = new CsvWriter(textWriter, new CsvConfiguration(CultureInfo.InvariantCulture));
501	            var lines = result.StringTable!.Select(x => new
502	            {
503	                id = x.Key,
504	                text = x.Value.text,
505	                file = x.Value.fileName,
506	                node = x.Value.nodeName,
507	                lineNumber = x.Value.lineNumber,
508	            });
509	            csv.WriteRecords(lines);
510	            textWriter.Flush();
511	            memoryStream.Position = 0;
512	            using var reader = new StreamReader(memoryStream);
513	            program.BaseLocalizationId = CultureInfo.CurrentCulture.Name;
514	            program.BaseLocalisationStringTable = reader.ReadToEnd();
515	            program.Localizations = new YarnTranslation[0];
516	        }
517	
518	        return program;
519	    }
520	}
