529	/// WASD/arrow movement for the tagged player (a mesh shape, feet at the transform), clamped so
530	/// the body stays inside the boundary. Frozen while a dialogue is active.
531	[With(typeof(PlayerTag), typeof(TransformComponent))]
532	public sealed class PlayerMovementSystem : AEntitySetSystem<GameState>
533	{
534	    private readonly float _halfWidth;
535	    private readonly float _halfHeight;
536	    private readonly float _speed;
537	    private readonly float _clampHalfWidth;
538	    private readonly float _clampHeight;
539	    private readonly Func<bool> _isFrozen;
540	
541	    public PlayerMovementSystem(World world, float halfWidth, float halfHeight, float speed,
542	        float clampHalfWidth, float clampHeight, Func<bool> isFrozen)
543	        : base(world)
544	    {
545	        _halfWidth = halfWidth;
546	        _halfHeight = halfHeight;
547	        _speed = speed;
548	        _clampHalfWidth = clampHalfWidth;
549	        _clampHeight = clampHeight;
550	        _isFrozen = isFrozen;
551	    }
552	
553	    protected override void Update(GameState state, in Entity entity)
554	    {
555	        if (_isFrozen()) return;
556	
557	        var keyboard = Keyboard.GetState();
558	        var dir = Vector2.Zero;
559	        if (keyboard.IsKeyDown(Keys.A) || keyboard.IsKeyDown(Keys.Left)) dir.X -= 1f;
560	        if (keyboard.IsKeyDown(Keys.D) || keyboard.IsKeyDown(Keys.Right)) dir.X += 1f;
561	        if (keyboard.IsKeyDown(Keys.W) || keyboard.IsKeyDown(Keys.Up)) dir.Y -= 1f;
562	        if (keyboard.IsKeyDown(Keys.S) || keyboard.IsKeyDown(Keys.Down)) dir.Y += 1f;
563	
564	        if (dir == Vector2.Zero) return;
565	
566	        dir.Normalize();
567	        var transform = entity.Get<TransformComponent>();
568	        var next = transform.Position + dir * _speed * state.Time;
569	        // Feet anchored at the position; keep the whole body (which rises _clampHeight above the
570	        // feet) inside the boundary.
571	        next.X = MathHelper.Clamp(next.X, -_halfWidth + _clampHalfWidth, _halfWidth - _clampHalfWidth);
572	        next.Y = MathHelper.Clamp(next.Y, -_halfHeight + _clampHeight, _halfHeight);
573	        transform.Position = next;
574	    }
575	}
576	
577	/// Shows a "press E" prompt when the player is near the NPC and, on the interact edge,
578	/// publishes a <see cref="DialogueStartMessage"/>. Suppressed while a dialogue is active.
579	public sealed class NpcInteractionSystem : ISystem<GameState>
580	{
581	    private readonly Entity _player;
582	    private readonly Entity _npc;
583	    private readonly Entity _prompt;
584	    private readonly AInputState _interact;
585	    private readonly float _rangeSq;
586	    private readonly Func<bool> _dialogueActive;
587	    private readonly World _world;
588	
589	    public bool IsEnabled { get; set; } = true;
590	
591	    public NpcInteractionSystem(World world, Entity player, Entity npc, Entity prompt,
592	        AInputState interact, float range, Func<bool> dialogueActive)
593	    {
594	        _world = world;
595	        _player = player;
596	        _npc = npc;
597	        _prompt = prompt;
598	        _interact = interact;
599	        _rangeSq = range * range;
600	        _dialogueActive = dialogueActive;
601	    }
602	
603	    public void Update(GameState state)
604	    {
605	        if (!IsEnabled || !_player.IsAlive || !_npc.IsAlive) return;
606	
607	        if (_dialogueActive())
608	        {
609	            SetPromptVisible(false);
610	            return;
611	        }
612	
613	        var playerPos = _player.Get<TransformComponent>().Position;
614	        var npcPos = _npc.Get<TransformComponent>().Position;
615	        var inRange = Vector2.DistanceSquared(playerPos, npcPos) <= _rangeSq;
616	
617	        SetPromptVisible(inRange);
618	
619	        if (inRange && _interact.JustPressed())
620	            _world.Publish(new DialogueStartMessage(_npc, "Start"));
621	    }
622	
623	    private void SetPromptVisible(bool visible)
624	    {
625	        if (!_prompt.IsAlive) return;
626	        var has = _prompt.Has<VisibleComponent>();
627	        if (visible && !has) _prompt.Set<VisibleComponent>();
628	        else if (!visible && has) _prompt.Remove<VisibleComponent>();
629	    }
630	
631	    public void Dispose() => GC.SuppressFinalize(this);
632	}
633	
634	/// A pair of entities making up one in-box portrait: a wood-brown frame (mesh) and the emote
635	/// face (sprite) drawn on top of it.
636	public readonly record struct PortraitSlot(Entity Frame, Entity Face);
637	
638	/// Above-head reaction marks. Subscribes to <see cref="DialogueCommandMessage"/>, reacts to
639	/// `react who mark` by showing a generated mesh glyph above the player or cow on the Main
640	/// target, and auto-hides it after a delay. Clears on dialogue end.
641	public sealed class ReactionMarkSystem : ISystem<GameState>
642	{
643	    private readonly Entity _playerMark;
644	    private readonly Entity _npcMark;
645	    private readonly float _duration;
646	    private readonly float _markSize;
647	
648	    public bool IsEnabled { get; set; } = true;
649	
650	    public ReactionMarkSystem(World world, Entity playerMark, Entity npcMark,
651	        float duration, float markSize)
652	    {
653	        _playerMark = playerMark;
654	        _npcMark = npcMark;
655	        _duration = duration;
656	        _markSize = markSize;
657	        world.Subscribe(this);
658	    }
659	
660	    [Subscribe]
661	    private void OnCommand(in DialogueCommandMessage msg)
662	    {
663	        var parts = msg.Command.Split(' ', StringSplitOptions.RemoveEmptyEntries);
664	        if (parts.Length < 3 || parts[0] != "react") return;
665	
666	        var target = parts[1] switch
667	        {
668	            "player" => _playerMark,
669	            "npc" => _npcMark,
670	            _ => default,
671	        };
672	        if (!target.IsAlive) return;
673	
674	        target.Set(new EmoteBubbleComponent { HideAt = float.NaN });
675	        if (!target.Has<VisibleComponent>()) target.Set<VisibleComponent>();
676	        target.Get<DrawComponent>().SetMeshData(DialogueGlyphs.ReactionMark(_markSize, parts[2]));
677	    }
678	
679	    [Subscribe]
680	    private void OnDialogueActive(in DialogueActiveMessage msg)
681	    {
682	        if (!msg.IsActive)
683	        {
684	            Hide(_playerMark);
685	            Hide(_npcMark);
686	        }
687	    }
688	
689	    public void Update(GameState state)
690	    {
691	        Expire(_playerMark, state.TotalTime);
692	        Expire(_npcMark, state.TotalTime);
693	    }
694	
695	    private void Expire(Entity mark, float now)
696	    {
697	        if (!mark.IsAlive || !mark.Has<EmoteBubbleComponent>()) return;
698	        ref var bubble = ref mark.Get<EmoteBubbleComponent>();
699	        if (float.IsNaN(bubble.HideAt)) { bubble.HideAt = now + _duration; return; }
700	        if (now >= bubble.HideAt) Hide(mark);
701	    }
702	
703	    // Main-target child — removing VisibleComponent is enough to hide it.
704	    private static void Hide(Entity mark)
705	    {
706	        if (!mark.IsAlive) return;
707	        if (mark.Has<VisibleComponent>()) mark.Remove<VisibleComponent>();
708	        if (mark.Has<EmoteBubbleComponent>()) mark.Remove<EmoteBubbleComponent>();
709	    }
710	
711	    public void Dispose() => GC.SuppressFinalize(this);
712	}
713	
714	/// In-box speaker portrait. Subscribes to <see cref="DialogueCommandMessage"/>; on
715	/// `emote who kind` it shows the framed mesh portrait of whoever is speaking in the single emote
716	/// frame (the box's left gutter). The NPC uses a cow-face glyph (`kind` ignored); the player
717	/// picks an emote-face glyph by `kind`. The portrait persists until the next `emote` or the
718	/// dialogue ends — it does not auto-expire (unlike reaction marks). Frame + face live on the UI
719	/// target, which always renders, so hiding empties the meshes rather than toggling VisibleComponent.
720	public sealed class DialoguePortraitSystem : ISystem<GameState>
721	{
722	    private readonly PortraitSlot _slot;
723	    private readonly MeshData _frameMesh;   // the static frame panel (shown on any emote)
724	    private readonly float _faceSize;
725	
726	    public bool IsEnabled { get; set; } = true;
727	
728	    public DialoguePortraitSystem(World world, PortraitSlot slot, float frameSize, float faceSize)
729	    {
730	        _slot = slot;
731	        _faceSize = faceSize;
732	        _frameMesh = ShapeBuilder.Panel(
733	            new Rectangle(0, 0, (int)frameSize, (int)frameSize), Color.Black, Color.White, 2f).Generate();
734	        world.Subscribe(this);
735	    }
736	
737	    [Subscribe]
738	    private void OnCommand(in DialogueCommandMessage msg)
739	    {
740	        var parts = msg.Command.Split(' ', StringSplitOptions.RemoveEmptyEntries);
741	        if (parts.Length < 3 || parts[0] != "emote") return;
742	
743	        switch (parts[1])
744	        {
745	            case "npc":
746	                ShowFace(DialogueGlyphs.CowFace(_faceSize).Generate()); // cow face, regardless of kind
747	                break;
748	            case "player":
749	                ShowFace(DialogueGlyphs.EmoteFace(_faceSize, parts[2]).Generate());
750	                break;
751	        }
752	    }
753	
754	    [Subscribe]
755	    private void OnDialogueActive(in DialogueActiveMessage msg)
756	    {
757	        if (!msg.IsActive)
758	        {
759	            ClearMesh(_slot.Frame);
760	            ClearMesh(_slot.Face);
761	        }
762	    }
763	
764	    public void Update(GameState state) { }
765	
766	    private void ShowFace(MeshData faceMesh)
767	    {
768	        // Show the (static) frame on the first emote, then swap in the speaker's face glyph.
769	        if (_slot.Frame.IsAlive) _slot.Frame.Get<DrawComponent>().SetMeshData(_frameMesh);
770	        if (_slot.Face.IsAlive) _slot.Face.Get<DrawComponent>().SetMeshData(faceMesh);
771	    }
772	
773	    private static void ClearMesh(Entity e)
774	    {
775	        if (!e.IsAlive || !e.Has<DrawComponent>()) return;
776	        ref var draw = ref e.Get<DrawComponent>();
777	        draw.Type = DrawElementType.Mesh;
778	        draw.Vertices = [];
779	        draw.Indices = [];
780	    }
781	
782	    public void Dispose() => GC.SuppressFinalize(this);
783	}
