833	/// Generated mesh glyphs for the dialogue scene — replaces the Sprout Lands character /
834	/// emote / icon sprites. World shapes are authored with the character's feet at the local
835	/// origin (body rising toward -Y); portrait faces fill a (0..size) box; reaction marks are
836	/// centred on the local origin.
837	internal static class DialogueGlyphs
838	{
839	    private static readonly Color Ink    = new(28, 30, 38);     // outlines, eyes, details
840	    private static readonly Color Player = new(86, 160, 196);   // player body
841	    private static readonly Color Cow    = new(224, 226, 230);  // cow body
842	    private static readonly Color Snout  = new(232, 160, 176);  // cow snout (pink)
843	    private static readonly Color Skin   = new(250, 224, 196);  // emote face
844	
845	    /// World player: a round body with two eyes, feet at the origin.
846	    public static IMeshGenerator PlayerShape(float r) =>
847	        new CompositeMeshGenerator()
848	            .Add(new CircleMeshGenerator(new Vector2(0, -r), r, Player, 28))
849	            .Add(new CircleOutlineMeshGenerator(new Vector2(0, -r), r, 2.5f, Ink, 28))
850	            .Add(new CircleMeshGenerator(new Vector2(-0.30f * r, -1.4f * r), 0.12f * r, Ink, 10))
851	            .Add(new CircleMeshGenerator(new Vector2(0.30f * r, -1.4f * r), 0.12f * r, Ink, 10));
852	
853	    /// World cow: a larger pale body with horns, a pink snout and eyes, feet at the origin.
854	    public static IMeshGenerator CowShape(float r) =>
855	        new CompositeMeshGenerator()
856	            .Add(new CircleMeshGenerator(new Vector2(0, -r), r, Cow, 28))
857	            .Add(new CircleOutlineMeshGenerator(new Vector2(0, -r), r, 2.5f, Ink, 28))
858	            .Add(new FilledTriangleMeshGenerator(
859	                new Vector2(-0.75f * r, -1.6f * r), new Vector2(-0.40f * r, -1.7f * r), new Vector2(-0.58f * r, -2.05f * r), Ink))
860	            .Add(new FilledTriangleMeshGenerator(
861	                new Vector2(0.75f * r, -1.6f * r), new Vector2(0.40f * r, -1.7f * r), new Vector2(0.58f * r, -2.05f * r), Ink))
862	            .Add(new CircleMeshGenerator(new Vector2(0, -0.55f * r), 0.40f * r, Snout, 18))
863	            .Add(new CircleOutlineMeshGenerator(new Vector2(0, -0.55f * r), 0.40f * r, 2f, Ink, 18))
864	            .Add(new CircleMeshGenerator(new Vector2(-0.35f * r, -1.35f * r), 0.11f * r, Ink, 10))
865	            .Add(new CircleMeshGenerator(new Vector2(0.35f * r, -1.35f * r), 0.11f * r, Ink, 10));
866	
867	    /// Player emote face glyph: a head with eyes and a mouth keyed by <paramref name="kind"/>.
868	    public static IMeshGenerator EmoteFace(float s, string kind)
869	    {
870	        var c = new Vector2(s / 2f, s / 2f);
871	        var face = new CompositeMeshGenerator()
872	            .Add(new CircleMeshGenerator(c, 0.40f * s, Skin, 24))
873	            .Add(new CircleOutlineMeshGenerator(c, 0.40f * s, 2f, Ink, 24))
874	            .Add(new CircleMeshGenerator(c + new Vector2(-0.16f * s, -0.05f * s), 0.045f * s, Ink, 10))
875	            .Add(new CircleMeshGenerator(c + new Vector2(0.16f * s, -0.05f * s), 0.045f * s, Ink, 10));
876	
877	        switch (kind)
878	        {
879	            case "sad":
880	                face.Add(new PolylineMeshGenerator(new[]
881	                {
882	                    c + new Vector2(-0.16f * s, 0.18f * s), c + new Vector2(0, 0.10f * s), c + new Vector2(0.16f * s, 0.18f * s),
883	                }, 2.5f, Ink));
884	                break;
885	            case "surprised":
886	                face.Add(new CircleOutlineMeshGenerator(c + new Vector2(0, 0.13f * s), 0.06f * s, 2f, Ink, 12));
887	                break;
888	            case "question":
889	                face.Add(new PolylineMeshGenerator(new[]
890	                {
891	                    c + new Vector2(-0.13f * s, 0.14f * s), c + new Vector2(0.13f * s, 0.14f * s),
892	                }, 2.5f, Ink));
893	                break;
894	            default: // happy / heart
895	                face.Add(new PolylineMeshGenerator(new[]
896	                {
897	                    c + new Vector2(-0.16f * s, 0.10f * s), c + new Vector2(0, 0.18f * s), c + new Vector2(0.16f * s, 0.10f * s),
898	                }, 2.5f, Ink));
899	                break;
900	        }
901	        return face;
902	    }
903	
904	    /// Cow portrait face glyph (centred in a 0..size box).
905	    public static IMeshGenerator CowFace(float s)
906	    {
907	        var c = new Vector2(s / 2f, s / 2f);
908	        return new CompositeMeshGenerator()
909	            .Add(new CircleMeshGenerator(c, 0.40f * s, Cow, 24))
910	            .Add(new CircleOutlineMeshGenerator(c, 0.40f * s, 2f, Ink, 24))
911	            .Add(new FilledTriangleMeshGenerator(
912	                c + new Vector2(-0.34f * s, -0.20f * s), c + new Vector2(-0.16f * s, -0.26f * s), c + new Vector2(-0.26f * s, -0.42f * s), Ink))
913	            .Add(new FilledTriangleMeshGenerator(
914	                c + new Vector2(0.34f * s, -0.20f * s), c + new Vector2(0.16f * s, -0.26f * s), c + new Vector2(0.26f * s, -0.42f * s), Ink))
915	            .Add(new CircleMeshGenerator(c + new Vector2(0, 0.16f * s), 0.16f * s, Snout, 16))
916	            .Add(new CircleOutlineMeshGenerator(c + new Vector2(0, 0.16f * s), 0.16f * s, 1.5f, Ink, 16))
917	            .Add(new CircleMeshGenerator(c + new Vector2(-0.16f * s, -0.05f * s), 0.045f * s, Ink, 10))
918	            .Add(new CircleMeshGenerator(c + new Vector2(0.16f * s, -0.05f * s), 0.045f * s, Ink, 10));
919	    }
920	
921	    /// An above-head reaction mark centred on the local origin: exclaim "!", star, or "?".
922	    public static IMeshGenerator ReactionMark(float s, string mark)
923	    {
924	        switch (mark)
925	        {
926	            case "star":
927	                return ShapeBuilder.Star(Vector2.Zero, 0.5f * s, 0.22f * s, 5, new Color(250, 205, 110));
928	            case "question":
929	                var cyan = new Color(120, 200, 235);
930	                return new CompositeMeshGenerator()
931	                    .Add(new PolylineMeshGenerator(new[]
932	                    {
933	                        new Vector2(-0.22f * s, -0.26f * s), new Vector2(-0.04f * s, -0.42f * s),
934	                        new Vector2(0.18f * s, -0.30f * s), new Vector2(0.16f * s, -0.08f * s),
935	                        new Vector2(0f, 0.02f * s), new Vector2(0f, 0.16f * s),
936	                    }, 4f, cyan))
937	                    .Add(new CircleMeshGenerator(new Vector2(0, 0.34f * s), 0.08f * s, cyan, 10));
938	            default: // exclaim
939	                var yellow = new Color(250, 210, 90);
940	                return new CompositeMeshGenerator()
941	                    .Add(new FilledRectangleMeshGenerator(
942	                        new Rectangle((int)(-0.09f * s), (int)(-0.5f * s), (int)(0.18f * s), (int)(0.6f * s)), yellow))
943	                    .Add(new CircleMeshGenerator(new Vector2(0, 0.4f * s), 0.10f * s, yellow, 10));
944	        }
945	    }
946	}
