359	    // --- Yarn callbacks (fire synchronously during Continue()) ---
360	
361	    private void OnYarnLine(Line line)
362	    {
363	        var text = _dialogueRunner.GetLocalizedTextForLine(line);
364	
365	        // Parse "Speaker: text" format
366	        string speaker = null;
367	        var displayText = text;
368	        var colonIndex = text.IndexOf(':');
369	        if (colonIndex > 0 && colonIndex < 30)
370	        {
371	            speaker = text[..colonIndex].Trim();
372	            displayText = text[(colonIndex + 1)..].Trim();
373	        }
374	
375	        // Wrap so long lines break onto new lines instead of overflowing the box. The reveal
376	        // animation slices the wrapped string, so embedded newlines just advance instantly.
377	        displayText = WrapText(displayText, _textAreaWidth);
378	
379	        _dialogueState.CurrentPhase = DialoguePhase.Line;
380	        _dialogueState.CurrentSpeaker = speaker;
381	        _dialogueState.WaitingForInput = false;
382	
383	        // Set text content and reset reveal animation
384	        ref var dynamicText = ref _dialogueState.TextEntity.Get<DynamicTextComponent>();
385	        dynamicText.TextContent = displayText;
386	        dynamicText.VisibleCharacterCount = 0;
387	        dynamicText.IsRevealed = false;
388	        dynamicText.RevealStartTime = float.NaN;
389	
390	        HideIndicator();
391	        HideOptions();
392	    }
393	
394	    private void OnYarnOptions(OptionSet optionSet)
395	    {
396	        _dialogueState.CurrentPhase = DialoguePhase.Options;
397	        _dialogueState.CurrentOptions.Clear();
398	        _dialogueState.CurrentOptionIDs.Clear();
399	        _dialogueState.SelectedOptionIndex = 0;
400	        _dialogueState.WaitingForInput = true;
401	
402	        foreach (var option in optionSet.Options)
403	        {
404	            if (!option.IsAvailable) continue;
405	            var text = _dialogueRunner.GetLocalizedTextForLine(option.Line);
406	            _dialogueState.CurrentOptions.Add(text);
407	            _dialogueState.CurrentOptionIDs.Add(option.ID);
408	        }
409	
410	        // Clear the main text line
411	        ref var dynamicText = ref _dialogueState.TextEntity.Get<DynamicTextComponent>();
412	        dynamicText.TextContent = "";
413	        dynamicText.VisibleCharacterCount = 0;
414	
415	        ShowOptions();
416	        HideIndicator();
417	    }
418	
419	    private void OnYarnCommand(Command command)
420	    {
421	        global::System.Diagnostics.Debug.WriteLine($"[Yarn Command] {command.Text}");
422	        // Surface the command so game code can react (emotes, SFX, flags), then flag the
423	        // conversation to flow past it on the next Update — see _pendingContinue.
424	        _world.Publish(new DialogueCommandMessage(command.Text));
425	        _pendingContinue = true;
426	    }
427	
428	    private void OnYarnNodeStart(string nodeName)
429	    {
430	        global::System.Diagnostics.Debug.WriteLine($"[Yarn] Node started: {nodeName}");
431	    }
432	
433	    private void OnYarnNodeComplete(string nodeName)
434	    {
435	        global::System.Diagnostics.Debug.WriteLine($"[Yarn] Node complete: {nodeName}");
436	    }
437	
438	    private void OnYarnDialogueComplete()
439	    {
440	        _dialogueState.CurrentPhase = DialoguePhase.Complete;
441	        DeactivateDialogue();
442	    }
443	
444	    // --- Dialogue start trigger ---
445	
446	    [Subscribe]
447	    private void OnDialogueStart(in DialogueStartMessage message)
448	    {
449	        if (_dialogueState.IsActive) return;
450	        StartYarnDialogue(message.StartNode);
451	    }
452	
453	    public void StartYarnDialogue(string nodeName)
454	    {
455	        _dialogueState.IsActive = true;
456	        _dialogueState.WasTriggered = true;
457	
458	        // The Interact press that opened this dialogue may still be held this same
459	        // frame. Consume the edge so DialogueSystem.Update (later in this tick)
460	        // doesn't read JustPressed and advance the first line on its own opening.
461	        _interact.Consume();
462	
463	        // Show dialogue box (and inner balloon, if any). In mesh mode fill the meshes (the
464	        // panels already carry VisibleComponent); in texture mode set VisibleComponent, which
465	        // gates SpritePrepSystem filling the nine-patch texture.
466	        if (_meshMode)
467	        {
468	            _dialogueState.BoxEntity.Get<DrawComponent>().SetMeshData(_boxMesh);
469	            if (_balloonMode) _balloonEntity.Get<DrawComponent>().SetMeshData(_balloonMesh);
470	        }
471	        else
472	        {
473	            _dialogueState.BoxEntity.Set<VisibleComponent>();
474	            if (_balloonMode) _balloonEntity.Set<VisibleComponent>();
475	        }
476	
477	        _world.Publish(new DialogueActiveMessage(true));
478	
479	        // Start the yarn node — fires LineHandler or OptionsHandler synchronously
480	        _yarnDialogue.SetNode(nodeName);
481	        _yarnDialogue.Continue();
482	    }
483	
484	    // --- Update loop ---
485	
486	    public void Update(GameState state)
487	    {
488	        if (!_dialogueState.IsActive) return;
489	
490	        // A <<command>> fired during the previous Continue(). Advance past it now, outside
491	        // the Yarn handler, so an inline command (e.g. <<emote ...>>) doesn't stall the line.
492	        if (_pendingContinue)
493	        {
494	            _pendingContinue = false;
495	            _yarnDialogue.Continue();
496	            if (!_dialogueState.IsActive) return; // command was the last thing before ===
497	        }
498	
499	        switch (_dialogueState.CurrentPhase)
500	        {
501	            case DialoguePhase.Line:
502	                UpdateLinePhase(_interact.JustPressed());
503	                break;
504	            case DialoguePhase.Options:
505	                UpdateOptionsPhase(
506	                    _up.JustPressed(),
507	                    _down.JustPressed(),
508	                    _interact.JustPressed());
509	                break;
510	        }
511	    }
512	
513	    private void UpdateLinePhase(bool interactJustPressed)
514	    {
515	        ref var dynamicText = ref _dialogueState.TextEntity.Get<DynamicTextComponent>();
516	
517	        if (dynamicText.IsRevealed)
518	        {
519	            ShowIndicator();
520	            _dialogueState.WaitingForInput = true;
521	        }
522	        else
523	        {
524	            HideIndicator();
525	        }
526	
527	        if (!interactJustPressed) return;
528	
529	        if (!dynamicText.IsRevealed)
530	        {
531	            // Skip reveal — show all text immediately
532	            dynamicText.VisibleCharacterCount = dynamicText.TextContent?.Length ?? 0;
533	            dynamicText.IsRevealed = true;
534	        }
535	        else
536	        {
537	            // Advance to next yarn content
538	            _yarnDialogue.Continue();
539	        }
540	    }
541	
542	    private void UpdateOptionsPhase(bool upJustPressed, bool downJustPressed, bool interactJustPressed)
543	    {
544	        if (upJustPressed)
545	        {
546	            _dialogueState.SelectedOptionIndex =
547	                Math.Max(0, _dialogueState.SelectedOptionIndex - 1);
548	            UpdateOptionHighlights();
549	        }
550	        else if (downJustPressed)
551	        {
552	            _dialogueState.SelectedOptionIndex =
553	                Math.Min(_dialogueState.CurrentOptions.Count - 1, _dialogueState.SelectedOptionIndex + 1);
554	            UpdateOptionHighlights();
555	        }
556	
557	        if (interactJustPressed)
558	        {
559	            var yarnOptionID = _dialogueState.CurrentOptionIDs[_dialogueState.SelectedOptionIndex];
560	            HideOptions();
561	            _yarnDialogue.SetSelectedOption(yarnOptionID);
562	            _yarnDialogue.Continue();
563	        }
564	    }
565	
566	    // --- Option entity management ---
567	
568	    private void ShowOptions()
569	    {
570	        HideOptions();
571	
572	        // Match the multi-line render advance (Font.LineHeight * scale * leading) so wrapped
573	        // options stack without overlap — see DynamicTextComponent.DefaultLineSpacing.
574	        var lineHeight = _font.LineHeight * _textScale * DynamicTextComponent.DefaultLineSpacing;
575	        var gap = lineHeight * 0.4f;
576	        var x = _textLocalPos.X;
577	        var y = _textLocalPos.Y;
578	
579	        for (var i = 0; i < _dialogueState.CurrentOptions.Count; i++)
580	        {
581	            var fullText = OptionDisplay(i);
582	
583	            var optionEntity = _world.CreateEntity();
584	            optionEntity.Set(new EntityInfoComponent(_entityInfoType, $"DialogueOption{i}"));
585	            optionEntity.Set(new TransformComponent(new Vector2(x, y)));
586	            optionEntity.SetParent(_rootEntity);
587	            optionEntity.Set(new DynamicTextComponent
588	            {
589	                Target = RenderTargetID.UI,
590	                LayerDepth = _overlayDepth,
591	                Font = _font,
592	                Color = i == _dialogueState.SelectedOptionIndex ? _optionSelectedColor : _lineColor,
593	                Scale = _textScale,
594	                RevealingSpeed = 0, // Instant reveal
595	                RevealStartTime = 0,
596	                IsRevealed = true,
597	                VisibleCharacterCount = fullText.Length,
598	                TextContent = fullText,
599	            });
600	            optionEntity.Set(new DrawComponent
601	            {
602	                Type = DrawElementType.Text,
603	                Target = RenderTargetID.UI
604	            });
605	            optionEntity.Set<VisibleComponent>();
606	
607	            _dialogueState.OptionEntities.Add(optionEntity);
608	
609	            // Advance by this option's wrapped height so multi-line options never overlap.
610	            var lines = CountLines(fullText);
611	            y += lines * lineHeight + gap;
612	        }
613	    }
614	
615	    private void UpdateOptionHighlights()
616	    {
617	        for (var i = 0; i < _dialogueState.OptionEntities.Count; i++)
618	        {
619	            var entity = _dialogueState.OptionEntities[i];
620	            if (!entity.IsAlive) continue;
621	
622	            ref var dt = ref entity.Get<DynamicTextComponent>();
623	            // The font is monospace and the "> "/"  " prefix is a fixed width, so re-wrapping
624	            // here can't change line count — option positions stay put across selection moves.
625	            dt.TextContent = OptionDisplay(i);
626	            dt.VisibleCharacterCount = dt.TextContent.Length;
627	            dt.Color = i == _dialogueState.SelectedOptionIndex ? _optionSelectedColor : _lineColor;
628	        }
629	    }
630	
631	    /// The selection-prefixed, wrapped text for option <paramref name="i"/>.
632	    private string OptionDisplay(int i)
633	    {
634	        var prefix = i == _dialogueState.SelectedOptionIndex ? "> " : "  ";
635	        var prefixWidth = _font.MeasureString(prefix).Width * _textScale;
636	        var wrapped = WrapText(_dialogueState.CurrentOptions[i], _textAreaWidth - prefixWidth);
637	        return prefix + wrapped;
638	    }
639	
640	    private static int CountLines(string text)
641	    {
642	        if (string.IsNullOrEmpty(text)) return 1;
643	        var n = 1;
644	        foreach (var c in text) if (c == '\n') n++;
645	        return n;
646	    }
647	
648	    /// Greedy word-wrap to <paramref name="maxWidth"/> rendered pixels (font measured at
649	    /// <see cref="_textScale"/>), inserting newlines. A single word wider than maxWidth is
650	    /// left on its own line rather than split.
651	    private string WrapText(string text, float maxWidth)
652	    {
653	        if (string.IsNullOrEmpty(text) || maxWidth <= 0) return text;
654	
655	        var result = new StringBuilder();
656	        var line = new StringBuilder();
657	        foreach (var word in text.Split(' ', StringSplitOptions.RemoveEmptyEntries))
658	        {
659	            var candidate = line.Length == 0 ? word : line + " " + word;
660	            if (line.Length > 0 && _font.MeasureString(candidate).Width * _textScale > maxWidth)
661	            {
662	                if (result.Length > 0) result.Append('\n');
663	                result.Append(line);
664	                line.Clear();
665	                line.Append(word);
666	            }
667	            else
668	            {
669	                if (line.Length > 0) line.Append(' ');
670	                line.Append(word);
671	            }
672	        }
673	        if (line.Length > 0)
674	        {
675	            if (result.Length > 0) result.Append('\n');
676	            result.Append(line);
677	        }
678	        return result.ToString();
679	    }
680	
681	    private void HideOptions()
682	    {
683	        foreach (var entity in _dialogueState.OptionEntities)
684	        {
685	            if (entity.IsAlive) entity.Dispose();
686	        }
687	        _dialogueState.OptionEntities.Clear();
688	    }
689	
690	    /// Shows the "continue" caret: fills the mesh in mesh mode, or sets VisibleComponent so
691	    /// SpritePrepSystem refills the sprite in texture mode.
692	    private void ShowIndicator()
693	    {
694	        if (_meshMode)
695	            _dialogueState.IndicatorEntity.Get<DrawComponent>().SetMeshData(_indicatorMesh);
696	        else if (!_dialogueState.IndicatorEntity.Has<VisibleComponent>())
697	            _dialogueState.IndicatorEntity.Set<VisibleComponent>();
698	    }
699	
700	    private void HideIndicator()
701	    {
702	        if (_meshMode)
703	        {
704	            EmptyMesh(_dialogueState.IndicatorEntity);
705	            return;
706	        }
707	
708	        if (_dialogueState.IndicatorEntity.Has<VisibleComponent>())
709	            _dialogueState.IndicatorEntity.Remove<VisibleComponent>();
710	
711	        // UI render target always renders regardless of VisibleComponent — clear the texture
712	        // so MasterRenderSystem skips drawing the stale DrawComponent.
713	        ref var indicatorDraw = ref _dialogueState.IndicatorEntity.Get<DrawComponent>();
714	        indicatorDraw.Texture = null;
715	    }
716	
717	    // --- Deactivation ---
718	
719	    private void DeactivateDialogue()
720	    {
721	        // Drop any pending command-continue so a command that coincides with the end of a
722	        // conversation (e.g. <<stop>>) can't leak a stray Continue() into the next dialogue.
723	        _pendingContinue = false;
724	        _dialogueState.IsActive = false;
725	        _dialogueState.WasTriggered = false;
726	        _dialogueState.CurrentPhase = DialoguePhase.None;
727	        _dialogueState.WaitingForInput = false;
728	        _dialogueState.CurrentSpeaker = null;
729	
730	        HideOptions();
731	
732	        // Hide box (and inner balloon): empty the meshes in mesh mode (VisibleComponent stays
733	        // on so MeshPrepSystem keeps updating the matrix), else drop the tag + texture.
734	        if (_meshMode)
735	        {
736	            EmptyMesh(_dialogueState.BoxEntity);
737	            if (_balloonMode) EmptyMesh(_balloonEntity);
738	        }
739	        else
740	        {
741	            if (_dialogueState.BoxEntity.Has<VisibleComponent>())
742	                _dialogueState.BoxEntity.Remove<VisibleComponent>();
743	            _dialogueState.BoxEntity.Get<DrawComponent>().Texture = null;
744	
745	            if (_balloonMode)
746	            {
747	                if (_balloonEntity.Has<VisibleComponent>())
748	                    _balloonEntity.Remove<VisibleComponent>();
749	                _balloonEntity.Get<DrawComponent>().Texture = null;
750	            }
751	        }
752	
753	        // Clear text
754	        ref var dynamicText = ref _dialogueState.TextEntity.Get<DynamicTextComponent>();
755	        dynamicText.VisibleCharacterCount = 0;
756	        dynamicText.IsRevealed = false;
757	        dynamicText.TextContent = "";
758	
759	        var textDraw = _dialogueState.TextEntity.Get<DrawComponent>();
760	        textDraw.Text = null;
761	        textDraw.Font = null;
762	
763	        // Hide indicator
764	        HideIndicator();
765	        var indicatorDraw = _dialogueState.IndicatorEntity.Get<DrawComponent>();
766	        indicatorDraw.Texture = null;
767	
768	        _world.Publish(new DialogueActiveMessage(false));
769	    }
770	
771	    // --- mesh chrome helpers ---
772	
773	    /// A filled rectangle behind a thick outline — the minimalist box panel.
774	    private static MeshData PanelMesh(Rectangle rect, Color fill, Color outline, float thickness)
775	        => new CompositeMeshGenerator()
776	            .Add(new FilledRectangleMeshGenerator(rect, fill))
777	            .Add(new RectangleOutlineMeshGenerator(rect, thickness, outline))
778	            .Generate();
779	
780	    /// A small downward-pointing "continue" caret triangle fitted to <paramref name="size"/>.
781	    private static MeshData DownCaretMesh(float size, Color color)
782	        => new FilledTriangleMeshGenerator(
783	            new Vector2(0.18f * size, 0.32f * size),
784	            new Vector2(0.82f * size, 0.32f * size),
785	            new Vector2(0.50f * size, 0.72f * size),
786	            color).Generate();
787	
788	    /// Empties an entity's mesh so MasterRenderSystem skips it (UI/HUD always render, so this
789	    /// is how a mesh is hidden there). Keeps Type = Mesh and the entity's VisibleComponent.
790	    private static void EmptyMesh(Entity e)
791	    {
792	        if (!e.IsAlive || !e.Has<DrawComponent>()) return;
793	        ref var draw = ref e.Get<DrawComponent>();
794	        draw.Type = DrawElementType.Mesh;
795	        draw.Vertices = [];
796	        draw.Indices = [];
797	    }
798	
799	    public void Dispose()
800	    {
801	        GC.SuppressFinalize(this);
802	    }
803	}
