636	/// Shows a "press E" prompt when the player is near the NPC and, on the interact edge,
637	/// publishes a <see cref="DialogueStartMessage"/>. Suppressed while a dialogue is active.
638	public sealed class NpcInteractionSystem : ISystem<GameState>
639	{
640	    private readonly Entity _player;
641	    private readonly Entity _npc;
642	    private readonly Entity _prompt;
643	    private readonly AInputState _interact;
644	    private readonly float _rangeSq;
645	    private readonly Func<bool> _dialogueActive;
646	    private readonly World _world;
647	
648	    public bool IsEnabled { get; set; } = true;
649	
650	    public NpcInteractionSystem(World world, Entity player, Entity npc, Entity prompt,
651	        AInputState interact, float range, Func<bool> dialogueActive)
652	    {
653	        _world = world;
654	        _player = player;
655	        _npc = npc;
656	        _prompt = prompt;
657	        _interact = interact;
658	        _rangeSq = range * range;
659	        _dialogueActive = dialogueActive;
660	    }
661	
662	    public void Update(GameState state)
663	    {
664	        if (!IsEnabled || !_player.IsAlive || !_npc.IsAlive) return;
665	
666	        if (_dialogueActive())
667	        {
668	            SetPromptVisible(false);
669	            return;
670	        }
671	
672	        var playerPos = _player.Get<TransformComponent>().Position;
673	        var npcPos = _npc.Get<TransformComponent>().Position;
674	        var inRange = Vector2.DistanceSquared(playerPos, npcPos) <= _rangeSq;
675	
676	        SetPromptVisible(inRange);
677	
678	        if (inRange && _interact.JustPressed())
679	            _world.Publish(new DialogueStartMessage(_npc, "Start"));
680	    }
681	
682	    private void SetPromptVisible(bool visible)
683	    {
684	        if (!_prompt.IsAlive) return;
685	        var has = _prompt.Has<VisibleComponent>();
686	        if (visible && !has) _prompt.Set<VisibleComponent>();
687	        else if (!visible && has) _prompt.Remove<VisibleComponent>();
688	    }
689	
690	    public void Dispose() => GC.SuppressFinalize(this);
691	}
