/// Concrete <see cref="AInputState"/> for the dialogue demo's per-action input.
public sealed class DemoInputState : AInputState { }

/// TEMP (verification only). When the MONODREAMS_DEMO_AUTO env var is "bird" or "cow", publishes
/// the matching <see cref="DialogueStartMessage"/> after a short delay so the headless render path
/// can screenshot the dialogue without keyboard input. Remove before finishing.
public sealed class DemoAutoTriggerSystem : ISystem<GameState>
{
    private readonly World _world;
    private readonly Entity _bird;
    private readonly Entity _npc;
    private int _frame;
    private bool _fired;
    public bool IsEnabled { get; set; } = true;

    public DemoAutoTriggerSystem(World world, Entity bird, Entity npc)
    {
        _world = world;
        _bird = bird;
        _npc = npc;
    }

    public void Update(GameState state)
    {
        if (_fired || ++_frame < 20) return;
        switch (global::System.Environment.GetEnvironmentVariable("MONODREAMS_DEMO_AUTO"))
        {
            case "bird": _world.Publish(new DialogueStartMessage(_bird, "Bird")); _fired = true; break;
            case "cow": _world.Publish(new DialogueStartMessage(_npc, "Start")); _fired = true; break;
        }
    }

    public void Dispose() => GC.SuppressFinalize(this);
}

