18	public class DialogueSystem : ISystem<GameState>
19	{
20	    private readonly World _world;
21	    private readonly Entity _rootEntity;
22	    private readonly DialogueStateComponent _dialogueState;
23	    private readonly BitmapFont _font;
24	    private readonly TransformComponent _rootTransform;
25	    private readonly float _layerDepth;
26	    private readonly string _entityInfoType;
27	    private readonly AInputState _interact;
28	    private readonly AInputState _up;
29	    private readonly AInputState _down;
30	
31	    // Set when a Yarn <<command>> fires mid-conversation. The post-command Continue() is
32	    // deferred to the next Update (see Update) rather than called re-entrantly inside the
33	    // Yarn command handler, which would risk faulting the VM.
34	    private bool _pendingContinue;
35	
36	    // Text layout (computed in the constructor, used by line + option rendering).
37	    private readonly float _textScale;
38	    private readonly Vector2 _textLocalPos; // UI-local top-left where the line text + options start
39	    private readonly float _textAreaWidth;
40	    private readonly float _overlayDepth;
41	
42	    // Balloon mode (optional): an inner "talk balloon" panel that wraps the text, with a left
43	    // gutter reserved for a game-drawn emote/portrait frame. When off, the legacy box + symmetric
44	    // sideInset layout is used. Activated by passing a talkBalloonTexture (see the constructor).
45	    private readonly bool _balloonMode;
46	    private readonly Entity _balloonEntity;
47	
48	    // Mesh chrome mode (optional): box / balloon / indicator are generated meshes (e.g. white
49	    // outline + black fill) instead of sprite nine-patches. Activated by passing chromeFill.
50	    // The texture path is untouched — MonoDreams.Examples still uses it. UI/HUD always render,
51	    // so these meshes are shown by filling their DrawComponent and hidden by emptying it.
52	    private readonly bool _meshMode;
53	    private readonly MeshData _boxMesh;
54	    private readonly MeshData _balloonMesh;
55	    private readonly MeshData _indicatorMesh;
56	    private readonly Color _lineColor;
57	    private readonly Color _optionSelectedColor;
58	
59	    // Anchored (world-space) mode (optional): instead of a fixed bottom-of-screen UI panel, the
60	    // whole dialogue floats above _anchorEntity on _renderTarget (Main) as a compact tailed
61	    // speech balloon, repositioned each frame to the anchor's world position. Mesh-mode only.
62	    private readonly RenderTargetID _renderTarget;
63	    private readonly bool _anchored;
64	    private readonly Entity _anchorEntity;
65	    private readonly Vector2 _anchorOffset;
66	    private readonly float _boxWidth;
67	    private readonly float _boxHeight;
68	    private readonly float _tailHeight;
69	
70	    // Downward speech-balloon tail height (anchored mode) — added below the box, pointing at the head.
71	    private const float AnchoredTailHeight = 22f;
72	
73	    /// UI-space rectangle of the left portrait gutter — the box's left region reserved for a
74	    /// game-drawn emote frame — when balloon mode is active; <see cref="Rectangle.Empty"/> otherwise.
75	    public Rectangle PortraitGutterBounds { get; }
76	
77	    // Yarn runtime
78	    private readonly Yarn.Dialogue _yarnDialogue;
79	    private readonly DialogueRunner _dialogueRunner;
80	    private readonly InMemoryVariableStorage _variableStorage;
81	
82	    public bool IsEnabled { get; set; } = true;
83	
84	    public DialogueSystem(
85	        World world,
86	        Texture2D? dialogBoxTexture,
87	        BitmapFont font,
88	        Texture2D? indicatorTexture,
89	        int virtualWidth,
90	        int virtualHeight,
91	        float layerDepth,
92	        AInputState interact,
93	        AInputState up,
94	        AInputState down,
95	        YarnProgram[] yarnPrograms,
96	        string entityInfoType = "Dialogue",
97	        float textScale = 0.32f,
98	        float sideInset = 0f,
99	        float indicatorSize = 44f,
100	        Texture2D? talkBalloonTexture = null,
101	        NinePatchInfo? talkBalloonNinePatch = null,
102	        float portraitGutter = 0f,
103	        float balloonPadding = 12f,
104	        float boxHeight = 120f,
105	        NinePatchInfo? boxNinePatch = null,
106	        // Mesh chrome (optional). Passing chromeFill switches box/balloon/indicator to
107	        // generated meshes; balloon mode then turns on whenever portraitGutter > 0.
108	        Color? chromeFill = null,
109	        Color? chromeOutline = null,
110	        float chromeThickness = 2f,
111	        Color? indicatorColor = null,
112	        // Anchored (world-space) presentation (optional). Passing anchorEntity floats the whole
113	        // dialogue above that entity on the given renderTarget (use Main), as a compact tailed
114	        // speech balloon that tracks the entity each frame. Requires mesh chrome (chromeFill).
115	        RenderTargetID renderTarget = RenderTargetID.UI,
116	        Entity? anchorEntity = null,
117	        Vector2 anchorOffset = default,
118	        float? boxWidthOverride = null)
119	    {
120	        _world = world;
121	        _font = font;
122	        _layerDepth = layerDepth;
123	        _entityInfoType = entityInfoType;
124	        _interact = interact;
125	        _up = up;
126	        _down = down;
127	        _textScale = textScale;
128	        _renderTarget = renderTarget;
129	        _anchored = anchorEntity.HasValue;
130	        _anchorEntity = anchorEntity ?? default;
131	        _anchorOffset = anchorOffset;
132	        world.Subscribe(this);
133	
134	        var overlayDepth = layerDepth + 0.01f;
135	        _overlayDepth = overlayDepth;
136	
137	        // Layout constants (UI coordinates, virtual resolution). By default the box fills the
138	        // screen width minus a margin and sits at the bottom; anchored balloons pass a compact
139	        // boxWidthOverride and are repositioned above their anchor each frame (see RepositionAnchor).
140	        const float boxMargin = 20f;
141	        var boxWidth = boxWidthOverride ?? (virtualWidth - 2f * boxMargin);
142	        var rootPosition = new Vector2(boxMargin, virtualHeight - boxHeight - boxMargin);
143	
144	        _meshMode = chromeFill.HasValue;
145	        // Anchored mode draws a tailed speech balloon on the Main target; it relies on the mesh
146	        // show/hide path and never reserves a portrait gutter.
147	        if (_anchored && !_meshMode)
148	            throw new ArgumentException(
149	                "Anchored dialogue requires mesh chrome — pass chromeFill.", nameof(anchorEntity));
150	        _boxWidth = boxWidth;
151	        _boxHeight = boxHeight;
152	        _tailHeight = _anchored ? AnchoredTailHeight : 0f;
153	        // In mesh mode the portrait gutter (not a balloon texture) decides balloon layout; anchored
154	        // mode forces the legacy text-on-box layout (no inner balloon / portrait gutter).
155	        _balloonMode = !_anchored && (_meshMode ? portraitGutter > 0f : talkBalloonTexture != null);
156	        _lineColor = _meshMode ? new Color(238, 232, 213) : Color.SaddleBrown;
157	        _optionSelectedColor = _meshMode ? new Color(250, 218, 147) : Color.White;
158	
159	        // Where the line text + options start, the text wrap width, and the continue indicator,
160	        // differ between balloon mode (text lives inside an inner panel, left gutter reserved for
161	        // a game-drawn emote frame) and legacy mode (text on the box, symmetric sideInset).
162	        Vector2 textLocal;
163	        Vector2 indicatorOffset;
164	        float balloonX = 0f, balloonY = 0f, balloonW = 0f, balloonH = 0f;
165	        if (_balloonMode)
166	        {
167	            const float vMargin = 10f;   // balloon inset from the box top/bottom
168	            const float rightMargin = 16f; // balloon inset from the box right edge
169	            balloonX = portraitGutter;
170	            balloonY = vMargin;
171	            balloonW = boxWidth - portraitGutter - rightMargin;
172	            balloonH = boxHeight - 2f * vMargin;
173	            textLocal = new Vector2(balloonX + balloonPadding, balloonY + balloonPadding);
174	            _textAreaWidth = balloonW - 2f * balloonPadding;
175	            indicatorOffset = new Vector2(
176	                balloonX + balloonW - indicatorSize - 10f,
177	                balloonY + balloonH - indicatorSize - 8f);
178	            // UI-space rect of the left gutter, for the demo to place its emote frame.
179	            PortraitGutterBounds = new Rectangle(
180	                (int)rootPosition.X, (int)rootPosition.Y, (int)portraitGutter, (int)boxHeight);
181	        }
182	        else
183	        {
184	            var textOffset = new Vector2(16, 16);
185	            // Line + option text wrap within the box minus symmetric side insets — the insets
186	            // reserve room on each side for a game-drawn portrait (see sideInset).
187	            textLocal = new Vector2(textOffset.X + sideInset, textOffset.Y);
188	            _textAreaWidth = boxWidth - 2f * textOffset.X - 2f * sideInset;
189	            // Continue marker sits at the bottom-right of the TEXT area (inset past any portrait).
190	            indicatorOffset = new Vector2(boxWidth - sideInset - indicatorSize - 12, boxHeight - indicatorSize - 8);
191	            PortraitGutterBounds = Rectangle.Empty;
192	        }
193	        _textLocalPos = textLocal;
194	
195	        // Pre-build the chrome meshes in mesh mode (authored in each entity's local space; the
196	        // entity transform/parent places them). Applied on activate, emptied on deactivate.
197	        if (_meshMode)
198	        {
199	            var fill = chromeFill!.Value;
200	            var outline = chromeOutline ?? Color.White;
201	            var boxRect = new Rectangle(0, 0, (int)boxWidth, (int)boxHeight);
202	            _boxMesh = _anchored
203	                ? BalloonMesh(boxRect, fill, outline, chromeThickness, _tailHeight)
204	                : PanelMesh(boxRect, fill, outline, chromeThickness);
205	            if (_balloonMode)
206	                _balloonMesh = new RectangleOutlineMeshGenerator(
207	                    new Rectangle(0, 0, (int)balloonW, (int)balloonH), chromeThickness, outline).Generate();
208	            _indicatorMesh = DownCaretMesh(indicatorSize, indicatorColor ?? Color.White);
209	        }
210	
211	        // Create root entity
212	        _rootTransform = new TransformComponent(rootPosition);
213	        _rootEntity = world.CreateEntity();
214	        _rootEntity.Set(new EntityInfoComponent(_entityInfoType, "DialogueRoot"));
215	        _rootEntity.Set(_rootTransform);
216	        _dialogueState = new DialogueStateComponent();
217	        _rootEntity.Set(_dialogueState);
218	
219	        // Create box child entity
220	        _dialogueState.BoxEntity = world.CreateEntity();
221	        _dialogueState.BoxEntity.Set(new EntityInfoComponent(_entityInfoType, "DialogueBox"));
222	        _dialogueState.BoxEntity.Set(new TransformComponent());
223	        _dialogueState.BoxEntity.SetParent(_rootEntity);
224	        if (_meshMode)
225	        {
226	            // Mesh box: empty until activated; VisibleComponent kept on so MeshPrepSystem
227	            // always refreshes the world matrix (UI renders regardless of the tag).
228	            _dialogueState.BoxEntity.Set(new DrawComponent
229	            {
230	                Type = DrawElementType.Mesh,
231	                Target = _renderTarget,
232	                LayerDepth = _layerDepth,
233	            });
234	            _dialogueState.BoxEntity.Set<VisibleComponent>();
235	        }
236	        else
237	        {
238	            _dialogueState.BoxEntity.Set(new SpriteInfoComponent
239	            {
240	                SpriteSheet = dialogBoxTexture,
241	                Source = new Rectangle(0, 0, dialogBoxTexture!.Width, dialogBoxTexture.Height),
242	                Size = new Vector2(boxWidth, boxHeight),
243	                Color = Color.White,
244	                Target = _renderTarget,
245	                LayerDepth = _layerDepth,
246	                // Default nine-patch suits the 128×48 "dialog box medium" art; pass boxNinePatch to
247	                // back the box with a different panel texture.
248	                NinePatchData = boxNinePatch ?? new NinePatchInfo(
249	                    23,
250	                    new Rectangle(0, 0, 23, 23),
251	                    new Rectangle(23, 0, 1, 23),
252	                    new Rectangle(24, 0, 23, 23),
253	                    new Rectangle(0, 23, 23, 1),
254	                    new Rectangle(23, 23, 1, 1),
255	                    new Rectangle(24, 23, 23, 1),
256	                    new Rectangle(0, 24, 23, 23),
257	                    new Rectangle(23, 24, 1, 23),
258	                    new Rectangle(24, 24, 23, 23))
259	            });
260	            _dialogueState.BoxEntity.Set(new DrawComponent
261	            {
262	                Type = DrawElementType.Sprite,
263	                Target = _renderTarget
264	            });
265	        }
266	
267	        // Create inner talk-balloon child (balloon mode only): a nine-patch panel that holds the
268	        // text/options/indicator, drawn just above the box and beside the left portrait gutter.
269	        if (_balloonMode)
270	        {
271	            _balloonEntity = world.CreateEntity();
272	            _balloonEntity.Set(new EntityInfoComponent(_entityInfoType, "DialogueBalloon"));
273	            _balloonEntity.Set(new TransformComponent(new Vector2(balloonX, balloonY)));
274	            _balloonEntity.SetParent(_rootEntity);
275	            if (_meshMode)
276	            {
277	                // Inner frame: outline only, so the box's fill shows through behind the text.
278	                _balloonEntity.Set(new DrawComponent
279	                {
280	                    Type = DrawElementType.Mesh,
281	                    Target = _renderTarget,
282	                    LayerDepth = _layerDepth + 0.005f,
283	                });
284	                _balloonEntity.Set<VisibleComponent>();
285	            }
286	            else
287	            {
288	                _balloonEntity.Set(new SpriteInfoComponent
289	                {
290	                    SpriteSheet = talkBalloonTexture,
291	                    Source = new Rectangle(0, 0, talkBalloonTexture!.Width, talkBalloonTexture.Height),
292	                    Size = new Vector2(balloonW, balloonH),
293	                    Color = Color.White,
294	                    Target = _renderTarget,
295	                    LayerDepth = _layerDepth + 0.005f, // between the box and the text/options
296	                    NinePatchData = talkBalloonNinePatch,
297	                });
298	                _balloonEntity.Set(new DrawComponent
299	                {
300	                    Type = DrawElementType.Sprite,
301	                    Target = _renderTarget
302	                });
303	            }
304	        }
305	
306	        // Create text child entity
307	        _dialogueState.TextEntity = world.CreateEntity();
308	        _dialogueState.TextEntity.Set(new EntityInfoComponent(_entityInfoType, "DialogueText"));
309	        _dialogueState.TextEntity.Set(new TransformComponent(_textLocalPos));
310	        _dialogueState.TextEntity.SetParent(_rootEntity);
311	        _dialogueState.TextEntity.Set(new DynamicTextComponent
312	        {
313	            Target = _renderTarget,
314	            LayerDepth = overlayDepth,
315	            Font = _font,
316	            Color = _lineColor,
317	            Scale = textScale,
318	            RevealingSpeed = 20,
319	            RevealStartTime = float.NaN,
320	            IsRevealed = false,
321	            VisibleCharacterCount = 0,
322	            TextContent = ""
323	        });
324	        _dialogueState.TextEntity.Set(new DrawComponent
325	        {
326	            Type = DrawElementType.Text,
327	            Target = _renderTarget
328	        });
329	        // The Main target consults VisibleComponent (UI/HUD always render); anchored dialogue
330	        // lives on Main, so the text needs the tag to be drawn. TextPrepSystem doesn't gate on it.
331	        if (_renderTarget != RenderTargetID.UI)
332	            _dialogueState.TextEntity.Set<VisibleComponent>();
333	
334	        // Create indicator child entity
335	        _dialogueState.IndicatorEntity = world.CreateEntity();
336	        _dialogueState.IndicatorEntity.Set(new EntityInfoComponent(_entityInfoType, "DialogueIndicator"));
337	        _dialogueState.IndicatorEntity.Set(new TransformComponent(indicatorOffset));
338	        _dialogueState.IndicatorEntity.SetParent(_rootEntity);
339	        if (_meshMode)
340	        {
341	            // Mesh caret: empty until a line is fully revealed; VisibleComponent kept on.
342	            _dialogueState.IndicatorEntity.Set(new DrawComponent
343	            {
344	                Type = DrawElementType.Mesh,
345	                Target = _renderTarget,
346	                LayerDepth = overlayDepth,
347	            });
348	            _dialogueState.IndicatorEntity.Set<VisibleComponent>();
349	        }
350	        else
351	        {
352	            _dialogueState.IndicatorEntity.Set(new SpriteInfoComponent
353	            {
354	                SpriteSheet = indicatorTexture,
355	                Source = new Rectangle(0, 0, indicatorTexture!.Width, indicatorTexture.Height),
356	                Size = new Vector2(indicatorSize, indicatorSize),
357	                Color = Color.White,
358	                Target = _renderTarget,
359	                LayerDepth = overlayDepth
360	            });
361	            _dialogueState.IndicatorEntity.Set(new DrawComponent
362	            {
363	                Type = DrawElementType.Sprite,
364	                Target = _renderTarget
365	            });
366	        }
367	
368	        // Set up Yarn runtime
369	        _dialogueRunner = new DialogueRunner();
370	        _variableStorage = new InMemoryVariableStorage();
371	        _yarnDialogue = new Yarn.Dialogue(_variableStorage)
372	        {
373	            LogDebugMessage = msg => global::System.Diagnostics.Debug.WriteLine($"[Yarn] {msg}"),
374	            LogErrorMessage = msg => global::System.Diagnostics.Debug.WriteLine($"[Yarn ERROR] {msg}"),
375	            LineHandler = OnYarnLine,
376	            OptionsHandler = OnYarnOptions,
377	            CommandHandler = OnYarnCommand,
378	            NodeStartHandler = OnYarnNodeStart,
379	            NodeCompleteHandler = OnYarnNodeComplete,
380	            DialogueCompleteHandler = OnYarnDialogueComplete,
381	        };
382	
383	        // Combine all yarn programs via protobuf merge
384	        Yarn.Program combinedProgram = null;
385	        foreach (var yarnProgram in yarnPrograms)
386	        {
387	            _dialogueRunner.AddStringTable(yarnProgram);
388	            var program = yarnProgram.GetProgram();
389	            if (combinedProgram == null)
390	            {
391	                combinedProgram = program;
392	            }
393	            else
394	            {
395	                combinedProgram.MergeFrom(program);
396	            }
397	        }
398	        _yarnDialogue.SetProgram(combinedProgram);
399	    }
