401	    // --- Yarn callbacks (fire synchronously during Continue()) ---
402	
403	    private void OnYarnLine(Line line)
404	    {
405	        var text = _dialogueRunner.GetLocalizedTextForLine(line);
406	
407	        // Parse "Speaker: text" format
408	        string speaker = null;
409	        var displayText = text;
410	        var colonIndex = text.IndexOf(':');
411	        if (colonIndex > 0 && colonIndex < 30)
412	        {
413	            speaker = text[..colonIndex].Trim();
414	            displayText = text[(colonIndex + 1)..].Trim();
415	        }
416	
417	        // Wrap so long lines break onto new lines instead of overflowing the box. The reveal
418	        // animation slices the wrapped string, so embedded newlines just advance instantly.
419	        displayText = WrapText(displayText, _textAreaWidth);
420	
421	        _dialogueState.CurrentPhase = DialoguePhase.Line;
422	        _dialogueState.CurrentSpeaker = speaker;
423	        _dialogueState.WaitingForInput = false;
424	
425	        // Set text content and reset reveal animation
426	        ref var dynamicText = ref _dialogueState.TextEntity.Get<DynamicTextComponent>();
427	        dynamicText.TextContent = displayText;
428	        dynamicText.VisibleCharacterCount = 0;
429	        dynamicText.IsRevealed = false;
430	        dynamicText.RevealStartTime = float.NaN;
431	
432	        HideIndicator();
433	        HideOptions();
434	    }
435	
436	    private void OnYarnOptions(OptionSet optionSet)
437	    {
438	        _dialogueState.CurrentPhase = DialoguePhase.Options;
439	        _dialogueState.CurrentOptions.Clear();
440	        _dialogueState.CurrentOptionIDs.Clear();
441	        _dialogueState.SelectedOptionIndex = 0;
442	        _dialogueState.WaitingForInput = true;
443	
444	        foreach (var option in optionSet.Options)
445	        {
446	            if (!option.IsAvailable) continue;
447	            var text = _dialogueRunner.GetLocalizedTextForLine(option.Line);
448	            _dialogueState.CurrentOptions.Add(text);
449	            _dialogueState.CurrentOptionIDs.Add(option.ID);
450	        }
451	
452	        // Clear the main text line
453	        ref var dynamicText = ref _dialogueState.TextEntity.Get<DynamicTextComponent>();
454	        dynamicText.TextContent = "";
455	        dynamicText.VisibleCharacterCount = 0;
456	
457	        ShowOptions();
458	        HideIndicator();
459	    }
