486	    // --- Dialogue start trigger ---
487	
488	    [Subscribe]
489	    private void OnDialogueStart(in DialogueStartMessage message)
490	    {
491	        if (_dialogueState.IsActive) return;
492	        // Route by node ownership: with multiple DialogueSystems registered, every instance
493	        // receives the message — only the one whose merged Yarn program contains the node reacts.
494	        if (!_yarnDialogue.NodeExists(message.StartNode)) return;
495	        StartYarnDialogue(message.StartNode);
496	    }
497	
498	    public void StartYarnDialogue(string nodeName)
499	    {
500	        _dialogueState.IsActive = true;
501	        _dialogueState.WasTriggered = true;
502	
503	        // The Interact press that opened this dialogue may still be held this same
504	        // frame. Consume the edge so DialogueSystem.Update (later in this tick)
505	        // doesn't read JustPressed and advance the first line on its own opening.
506	        _interact.Consume();
507	
508	        // Show dialogue box (and inner balloon, if any). In mesh mode fill the meshes (the
509	        // panels already carry VisibleComponent); in texture mode set VisibleComponent, which
510	        // gates SpritePrepSystem filling the nine-patch texture.
511	        if (_meshMode)
512	        {
513	            _dialogueState.BoxEntity.Get<DrawComponent>().SetMeshData(_boxMesh);
514	            if (_balloonMode) _balloonEntity.Get<DrawComponent>().SetMeshData(_balloonMesh);
515	        }
516	        else
517	        {
518	            _dialogueState.BoxEntity.Set<VisibleComponent>();
519	            if (_balloonMode) _balloonEntity.Set<VisibleComponent>();
520	        }
521	
522	        // Anchored mode: place the balloon above the anchor now so it appears in the right spot
523	        // on the first frame (Update also re-runs this each frame to track the anchor).
524	        RepositionAnchor();
525	
526	        _world.Publish(new DialogueActiveMessage(true));
527	
528	        // Start the yarn node — fires LineHandler or OptionsHandler synchronously
529	        _yarnDialogue.SetNode(nodeName);
530	        _yarnDialogue.Continue();
531	    }
532	
533	    // --- Update loop ---
534	
535	    public void Update(GameState state)
536	    {
537	        if (!_dialogueState.IsActive) return;
538	
539	        // Anchored mode: keep the balloon floating above its anchor as the entity (or camera) moves.
540	        RepositionAnchor();
541	
542	        // A <<command>> fired during the previous Continue(). Advance past it now, outside
543	        // the Yarn handler, so an inline command (e.g. <<emote ...>>) doesn't stall the line.
544	        if (_pendingContinue)
545	        {
546	            _pendingContinue = false;
547	            _yarnDialogue.Continue();
548	            if (!_dialogueState.IsActive) return; // command was the last thing before ===
549	        }
550	
551	        switch (_dialogueState.CurrentPhase)
552	        {
553	            case DialoguePhase.Line:
554	                UpdateLinePhase(_interact.JustPressed());
555	                break;
556	            case DialoguePhase.Options:
557	                UpdateOptionsPhase(
558	                    _up.JustPressed(),
559	                    _down.JustPressed(),
560	                    _interact.JustPressed());
561	                break;
562	        }
563	    }
564	
565	    private void UpdateLinePhase(bool interactJustPressed)
566	    {
567	        ref var dynamicText = ref _dialogueState.TextEntity.Get<DynamicTextComponent>();
568	
569	        if (dynamicText.IsRevealed)
570	        {
571	            ShowIndicator();
572	            _dialogueState.WaitingForInput = true;
573	        }
574	        else
575	        {
576	            HideIndicator();
577	        }
578	
579	        if (!interactJustPressed) return;
580	
581	        if (!dynamicText.IsRevealed)
582	        {
583	            // Skip reveal — show all text immediately
584	            dynamicText.VisibleCharacterCount = dynamicText.TextContent?.Length ?? 0;
585	            dynamicText.IsRevealed = true;
586	        }
587	        else
588	        {
589	            // Advance to next yarn content
590	            _yarnDialogue.Continue();
591	        }
592	    }
593	
594	    private void UpdateOptionsPhase(bool upJustPressed, bool downJustPressed, bool interactJustPressed)
595	    {
596	        if (upJustPressed)
597	        {
598	            _dialogueState.SelectedOptionIndex =
599	                Math.Max(0, _dialogueState.SelectedOptionIndex - 1);
600	            UpdateOptionHighlights();
601	        }
602	        else if (downJustPressed)
603	        {
604	            _dialogueState.SelectedOptionIndex =
605	                Math.Min(_dialogueState.CurrentOptions.Count - 1, _dialogueState.SelectedOptionIndex + 1);
606	            UpdateOptionHighlights();
607	        }
608	
609	        if (interactJustPressed)
610	        {
611	            var yarnOptionID = _dialogueState.CurrentOptionIDs[_dialogueState.SelectedOptionIndex];
612	            HideOptions();
613	            _yarnDialogue.SetSelectedOption(yarnOptionID);
614	            _yarnDialogue.Continue();
615	        }
616	    }
617	
618	    // --- Option entity management ---
619	
620	    private void ShowOptions()
621	    {
622	        HideOptions();
623	
624	        // Match the multi-line render advance (Font.LineHeight * scale * leading) so wrapped
625	        // options stack without overlap — see DynamicTextComponent.DefaultLineSpacing.
626	        var lineHeight = _font.LineHeight * _textScale * DynamicTextComponent.DefaultLineSpacing;
627	        var gap = lineHeight * 0.4f;
628	        var x = _textLocalPos.X;
629	        var y = _textLocalPos.Y;
630	
631	        for (var i = 0; i < _dialogueState.CurrentOptions.Count; i++)
632	        {
633	            var fullText = OptionDisplay(i);
634	
635	            var optionEntity = _world.CreateEntity();
636	            optionEntity.Set(new EntityInfoComponent(_entityInfoType, $"DialogueOption{i}"));
637	            optionEntity.Set(new TransformComponent(new Vector2(x, y)));
638	            optionEntity.SetParent(_rootEntity);
639	            optionEntity.Set(new DynamicTextComponent
640	            {
641	                Target = _renderTarget,
642	                LayerDepth = _overlayDepth,
643	                Font = _font,
644	                Color = i == _dialogueState.SelectedOptionIndex ? _optionSelectedColor : _lineColor,
645	                Scale = _textScale,
646	                RevealingSpeed = 0, // Instant reveal
647	                RevealStartTime = 0,
648	                IsRevealed = true,
649	                VisibleCharacterCount = fullText.Length,
650	                TextContent = fullText,
651	            });
652	            optionEntity.Set(new DrawComponent
653	            {
654	                Type = DrawElementType.Text,
655	                Target = _renderTarget
656	            });
657	            optionEntity.Set<VisibleComponent>();
658	
659	            _dialogueState.OptionEntities.Add(optionEntity);
660	
661	            // Advance by this option's wrapped height so multi-line options never overlap.
662	            var lines = CountLines(fullText);
663	            y += lines * lineHeight + gap;
664	        }
665	    }
666	
667	    private void UpdateOptionHighlights()
668	    {
669	        for (var i = 0; i < _dialogueState.OptionEntities.Count; i++)
670	        {
671	            var entity = _dialogueState.OptionEntities[i];
672	            if (!entity.IsAlive) continue;
673	
674	            ref var dt = ref entity.Get<DynamicTextComponent>();
675	            // The font is monospace and the "> "/"  " prefix is a fixed width, so re-wrapping
676	            // here can't change line count — option positions stay put across selection moves.
677	            dt.TextContent = OptionDisplay(i);
678	            dt.VisibleCharacterCount = dt.TextContent.Length;
679	            dt.Color = i == _dialogueState.SelectedOptionIndex ? _optionSelectedColor : _lineColor;
680	        }
681	    }
682	
683	    /// The selection-prefixed, wrapped text for option <paramref name="i"/>.
684	    private string OptionDisplay(int i)
685	    {
686	        var prefix = i == _dialogueState.SelectedOptionIndex ? "> " : "  ";
687	        var prefixWidth = _font.MeasureString(prefix).Width * _textScale;
688	        var wrapped = WrapText(_dialogueState.CurrentOptions[i], _textAreaWidth - prefixWidth);
689	        return prefix + wrapped;
690	    }
691	
692	    private static int CountLines(string text)
693	    {
694	        if (string.IsNullOrEmpty(text)) return 1;
695	        var n = 1;
696	        foreach (var c in text) if (c == '\n') n++;
697	        return n;
698	    }
699	
700	    /// Greedy word-wrap to <paramref name="maxWidth"/> rendered pixels (font measured at
701	    /// <see cref="_textScale"/>), inserting newlines. A single word wider than maxWidth is
702	    /// left on its own line rather than split.
703	    private string WrapText(string text, float maxWidth)
704	    {
705	        if (string.IsNullOrEmpty(text) || maxWidth <= 0) return text;
706	
707	        var result = new StringBuilder();
708	        var line = new StringBuilder();
709	        foreach (var word in text.Split(' ', StringSplitOptions.RemoveEmptyEntries))
710	        {
711	            var candidate = line.Length == 0 ? word : line + " " + word;
712	            if (line.Length > 0 && _font.MeasureString(candidate).Width * _textScale > maxWidth)
713	            {
714	                if (result.Length > 0) result.Append('\n');
715	                result.Append(line);
716	                line.Clear();
717	                line.Append(word);
718	            }
719	            else
720	            {
721	                if (line.Length > 0) line.Append(' ');
722	                line.Append(word);
723	            }
724	        }
725	        if (line.Length > 0)
726	        {
727	            if (result.Length > 0) result.Append('\n');
728	            result.Append(line);
729	        }
730	        return result.ToString();
731	    }
732	
733	    private void HideOptions()
734	    {
735	        foreach (var entity in _dialogueState.OptionEntities)
736	        {
737	            if (entity.IsAlive) entity.Dispose();
738	        }
739	        _dialogueState.OptionEntities.Clear();
740	    }
