742	    /// Shows the "continue" caret: fills the mesh in mesh mode, or sets VisibleComponent so
743	    /// SpritePrepSystem refills the sprite in texture mode.
744	    private void ShowIndicator()
745	    {
746	        if (_meshMode)
747	            _dialogueState.IndicatorEntity.Get<DrawComponent>().SetMeshData(_indicatorMesh);
748	        else if (!_dialogueState.IndicatorEntity.Has<VisibleComponent>())
749	            _dialogueState.IndicatorEntity.Set<VisibleComponent>();
750	    }
751	
752	    private void HideIndicator()
753	    {
754	        if (_meshMode)
755	        {
756	            EmptyMesh(_dialogueState.IndicatorEntity);
757	            return;
758	        }
759	
760	        if (_dialogueState.IndicatorEntity.Has<VisibleComponent>())
761	            _dialogueState.IndicatorEntity.Remove<VisibleComponent>();
762	
763	        // UI render target always renders regardless of VisibleComponent — clear the texture
764	        // so MasterRenderSystem skips drawing the stale DrawComponent.
765	        ref var indicatorDraw = ref _dialogueState.IndicatorEntity.Get<DrawComponent>();
766	        indicatorDraw.Texture = null;
767	    }
