769	    // --- Deactivation ---
770	
771	    private void DeactivateDialogue()
772	    {
773	        // Drop any pending command-continue so a command that coincides with the end of a
774	        // conversation (e.g. <<stop>>) can't leak a stray Continue() into the next dialogue.
775	        _pendingContinue = false;
776	        _dialogueState.IsActive = false;
777	        _dialogueState.WasTriggered = false;
778	        _dialogueState.CurrentPhase = DialoguePhase.None;
779	        _dialogueState.WaitingForInput = false;
780	        _dialogueState.CurrentSpeaker = null;
781	
782	        HideOptions();
783	
784	        // Hide box (and inner balloon): empty the meshes in mesh mode (VisibleComponent stays
785	        // on so MeshPrepSystem keeps updating the matrix), else drop the tag + texture.
786	        if (_meshMode)
787	        {
788	            EmptyMesh(_dialogueState.BoxEntity);
789	            if (_balloonMode) EmptyMesh(_balloonEntity);
790	        }
791	        else
792	        {
793	            if (_dialogueState.BoxEntity.Has<VisibleComponent>())
794	                _dialogueState.BoxEntity.Remove<VisibleComponent>();
795	            _dialogueState.BoxEntity.Get<DrawComponent>().Texture = null;
796	
797	            if (_balloonMode)
798	            {
799	                if (_balloonEntity.Has<VisibleComponent>())
800	                    _balloonEntity.Remove<VisibleComponent>();
801	                _balloonEntity.Get<DrawComponent>().Texture = null;
802	            }
803	        }
804	
805	        // Clear text
806	        ref var dynamicText = ref _dialogueState.TextEntity.Get<DynamicTextComponent>();
807	        dynamicText.VisibleCharacterCount = 0;
808	        dynamicText.IsRevealed = false;
809	        dynamicText.TextContent = "";
810	
811	        var textDraw = _dialogueState.TextEntity.Get<DrawComponent>();
812	        textDraw.Text = null;
813	        textDraw.Font = null;
814	
815	        // Hide indicator
816	        HideIndicator();
817	        var indicatorDraw = _dialogueState.IndicatorEntity.Get<DrawComponent>();
818	        indicatorDraw.Texture = null;
819	
820	        _world.Publish(new DialogueActiveMessage(false));
821	    }
822	
823	    // --- anchored (world-space) mode ---
824	
825	    /// In anchored mode, place the balloon above the anchor entity: centred over it horizontally
826	    /// and lifted so the tail tip sits at <c>anchor.WorldPosition + _anchorOffset</c>. Mutating the
827	    /// root transform marks the child chain dirty; HierarchySystem (later in the pipeline) re-lays
828	    /// the box/text/indicator. No-op when not anchored or the anchor is gone.
829	    private void RepositionAnchor()
830	    {
831	        if (!_anchored || !_anchorEntity.IsAlive) return;
832	        var anchor = _anchorEntity.Get<TransformComponent>().WorldPosition;
833	        _rootTransform.Position = new Vector2(
834	            anchor.X + _anchorOffset.X - _boxWidth / 2f,
835	            anchor.Y + _anchorOffset.Y - _boxHeight - _tailHeight);
836	    }
837	
838	    // --- mesh chrome helpers ---
839	
840	    /// A filled rectangle behind a thick outline — the minimalist box panel.
841	    private static MeshData PanelMesh(Rectangle rect, Color fill, Color outline, float thickness)
842	        => new CompositeMeshGenerator()
843	            .Add(new FilledRectangleMeshGenerator(rect, fill))
844	            .Add(new RectangleOutlineMeshGenerator(rect, thickness, outline))
845	            .Generate();
846	
847	    /// A panel with a downward tail at its bottom-centre — the speech-balloon chrome used in
848	    /// anchored mode. The tail apex sits <paramref name="tailHeight"/> below the box bottom and
849	    /// points at the anchored entity's head.
850	    private static MeshData BalloonMesh(Rectangle rect, Color fill, Color outline, float thickness, float tailHeight)
851	    {
852	        var cx = rect.X + rect.Width / 2f;
853	        var by = rect.Y + rect.Height;
854	        var half = MathHelper.Clamp(rect.Width * 0.05f, 9f, 20f);
855	        var apex = new Vector2(cx, by + tailHeight);
856	        var left = new Vector2(cx - half, by);
857	        var right = new Vector2(cx + half, by);
858	        return new CompositeMeshGenerator()
859	            .Add(new FilledRectangleMeshGenerator(rect, fill))
860	            .Add(new FilledTriangleMeshGenerator(left, right, apex, fill))
861	            .Add(new RectangleOutlineMeshGenerator(rect, thickness, outline))
862	            .Add(new PolylineMeshGenerator(new[] { left, apex, right }, thickness, outline))
863	            .Generate();
864	    }
865	
866	    /// A small downward-pointing "continue" caret triangle fitted to <paramref name="size"/>.
867	    private static MeshData DownCaretMesh(float size, Color color)
868	        => new FilledTriangleMeshGenerator(
869	            new Vector2(0.18f * size, 0.32f * size),
870	            new Vector2(0.82f * size, 0.32f * size),
871	            new Vector2(0.50f * size, 0.72f * size),
872	            color).Generate();
873	
874	    /// Empties an entity's mesh so MasterRenderSystem skips it (UI/HUD always render, so this
875	    /// is how a mesh is hidden there). Keeps Type = Mesh and the entity's VisibleComponent.
876	    private static void EmptyMesh(Entity e)
877	    {
878	        if (!e.IsAlive || !e.Has<DrawComponent>()) return;
879	        ref var draw = ref e.Get<DrawComponent>();
880	        draw.Type = DrawElementType.Mesh;
881	        draw.Vertices = [];
882	        draw.Indices = [];
883	    }
884	
885	    public void Dispose()
886	    {
887	        GC.SuppressFinalize(this);
888	    }
889	}
