35	/// Dialogue module demo. A very basic top-down scene drawn entirely with generated meshes:
36	/// walk the player blob around a grass field with WASD, approach the cow NPC at the top-left,
37	/// and press E to start a Yarn conversation. The line text wraps and reveals
38	/// character-by-character; pick a reply with the up/down arrows and E. Yarn
39	/// <c>&lt;&lt;emote who kind&gt;&gt;</c> commands show the speaker's framed mesh portrait inside
40	/// the box and <c>&lt;&lt;react who mark&gt;&gt;</c> pops a mesh reaction mark above a head.
41	///
42	/// Showcases the dialogue module (<see cref="DialogueSystem"/> + Yarn runtime, fed an
43	/// in-memory-compiled program so the demo ships no .yarn asset) in its mesh-chrome mode, the
44	/// rendering-text reveal, and procedural mesh rendering on the Main/UI targets.
45	public class DialogueDemoScreen : IGameScreen
46	{
