55	    private const float ReactionMarkSize = 36f;   // above-head mesh glyph size
56	
57	    // Dialogue-box tuning passed into DialogueSystem. The box is now generated meshes
58	    // (white outline, black fill) with a left gutter holding a framed emote glyph.
