225	    /// The grass field: a filled green rectangle covering the boundary, with a faint grid
226	    /// of lines for texture. Replaces the old grass tile sprites.
227	    private void CreateGround()
228	    {
229	        var field = new Rectangle(
230	            -(int)BoundaryHalfWidth, -(int)BoundaryHalfHeight,
231	            (int)BoundaryHalfWidth * 2, (int)BoundaryHalfHeight * 2);
232	        ShapeBuilder.Filled(_world, field, new Color(58, 92, 64), RenderTargetID.Main, depth: 0.08f);
233	
234	        // Faint grid lines so the field reads as ground rather than a flat block.
235	        const float step = 80f;
236	        var grid = new CompositeMeshGenerator();
237	        var lineColor = new Color(72, 110, 78);
238	        for (var x = field.Left + (int)step; x < field.Right; x += (int)step)
239	            grid.Add(new LineMeshGenerator(new Vector2(x, field.Top), new Vector2(x, field.Bottom), 1f, lineColor));
240	        for (var y = field.Top + (int)step; y < field.Bottom; y += (int)step)
241	            grid.Add(new LineMeshGenerator(new Vector2(field.Left, y), new Vector2(field.Right, y), 1f, lineColor));
242	        ShapeBuilder.Create(_world, grid, RenderTargetID.Main, depth: 0.09f);
243	    }
