245	    private void CreateBoundary()
246	    {
247	        var bounds = new Rectangle(
248	            -(int)BoundaryHalfWidth, -(int)BoundaryHalfHeight,
249	            (int)BoundaryHalfWidth * 2, (int)BoundaryHalfHeight * 2);
250	
251	        var boundary = _world.CreateEntity();
252	        boundary.Set(new TransformComponent(Vector2.Zero));
253	        var draw = new DrawComponent { Target = RenderTargetID.Main, LayerDepth = 0.2f };
254	        draw.SetMeshData(new RectangleOutlineMeshGenerator(bounds, thickness: 2f, color: DemoPalette.TextLight));
255	        boundary.Set(draw);
256	        boundary.Set<VisibleComponent>();
