259	    /// Returns the player's above-head reaction-mark child (hidden until a `<<react>>` command).
260	    private Entity CreatePlayer()
261	    {
262	        _player = _world.CreateEntity();
263	        _player.Set(new EntityInfoComponent("Player", "DialogueDemoPlayer"));
264	        _player.Set(new TransformComponent(PlayerSpawn));
265	        _player.Set(new PlayerTag());
266	        var draw = new DrawComponent { Target = RenderTargetID.Main, LayerDepth = 0.50f };
267	        draw.SetMeshData(DialogueGlyphs.PlayerShape(PlayerBodyRadius));
268	        _player.Set(draw);
269	        _player.Set<VisibleComponent>();
270	
271	        return CreateReactionChild(_player, new Vector2(0, -2f * PlayerBodyRadius - 20f));
272	    }
273	
274	    /// Creates an NPC mesh character at <paramref name="position"/> (feet at the transform) with an
275	    /// above-head reaction-mark child and an "in range" interact prompt. Returns the NPC entity via
276	    /// <paramref name="npc"/> and (its reaction-mark child, its prompt child).
277	    private (Entity mark, Entity prompt) CreateNpc(
278	        out Entity npc, Vector2 position, IMeshGenerator shape, string infoName,
279	        float bodyRadius, string promptText)
280	    {
281	        npc = _world.CreateEntity();
282	        npc.Set(new EntityInfoComponent("NPC", infoName));
283	        npc.Set(new TransformComponent(position));
284	        var draw = new DrawComponent { Target = RenderTargetID.Main, LayerDepth = 0.50f };
285	        draw.SetMeshData(shape);
286	        npc.Set(draw);
287	        npc.Set<VisibleComponent>();
288	
289	        var mark = CreateReactionChild(npc, new Vector2(0, -2f * bodyRadius - 18f));
290	
291	        // Interact prompt centred just above the head — shown only when the player is in range.
292	        const float promptScale = 0.26f;
