329	    /// Creates the single in-box emote portrait — a mesh frame (white outline, black fill) with
330	    /// the speaker's mesh face glyph inside — centred in the dialogue box's left gutter (see
331	    /// DialogueSystem.PortraitGutterBounds). Both start with empty meshes; DialoguePortraitSystem
332	    /// fills them on an &lt;&lt;emote&gt;&gt; command and empties them on dialogue end.
333	    private PortraitSlot CreatePortraitSlot(Rectangle gutter)
334	    {
335	        var frameTopLeft = new Vector2(
336	            gutter.X + (gutter.Width - FrameRenderSize) / 2f,
337	            gutter.Y + (gutter.Height - FrameRenderSize) / 2f);
338	        var faceOffset = (FrameRenderSize - FaceRenderSize) / 2f;
339	
340	        // Frame — a mesh panel on UI, empty until the first <<emote>>; VisibleComponent kept on so
341	        // MeshPrepSystem keeps its matrix fresh (UI renders regardless of the tag).
342	        var frame = _world.CreateEntity();
343	        frame.Set(new EntityInfoComponent("DialogueDemo", "PortraitFrame"));
344	        frame.Set(new TransformComponent(frameTopLeft));
345	        frame.Set(new DrawComponent { Type = DrawElementType.Mesh, Target = RenderTargetID.UI, LayerDepth = 0.92f });
346	        frame.Set<VisibleComponent>();
347	
348	        // Speaker face — a mesh glyph on UI, drawn on top of the frame window.
349	        var face = _world.CreateEntity();
350	        face.Set(new EntityInfoComponent("DialogueDemo", "PortraitFace"));
351	        face.Set(new TransformComponent(frameTopLeft + new Vector2(faceOffset, faceOffset)));
352	        face.Set(new DrawComponent { Type = DrawElementType.Mesh, Target = RenderTargetID.UI, LayerDepth = 0.93f });
353	        face.Set<VisibleComponent>();
354	
355	        return new PortraitSlot(frame, face);
356	    }
