534	    /// The bird conversation, played by the anchored (over-head balloon) DialogueSystem. Kept
535	    /// short — lines and options fit the compact bubble. Only `<<react>>` commands are used (the
536	    /// balloon has no portrait gutter); the start node must be named "Bird" (see the npc targets).
537	    private const string BirdYarnSource = @"title: Bird
538	---
539	<<react bird exclaim>>
540	Robin: Tweet! Up here! Mind your step down there, friend.
541	Robin: Not many two-leggers stop to say hello. What's on your mind?
542	-> Nice view from up here?
543	    <<react bird star>>
544	    Robin: The best! The whole meadow, and the cow's silly face.
545	-> Seen anything interesting?
546	    <<react player question>>
547	    Robin: A shiny pebble by the fence. I may have borrowed it.
548	    <<react bird star>>
549	-> Just saying hi.
550	    <<react player exclaim>>
551	    Robin: Ha! A bird does love good manners. Tweet!
552	Robin: Off I go. Mind the puddles!
553	<<react bird star>>
554	===
555	";
556	
557	    /// Compiles a Yarn source string into a runtime <see cref="YarnProgram"/>, mirroring
558	    /// what <c>YarnSpinnerProcessor</c> does at content-build time — so the demo ships no
559	    /// .yarn asset. The required deps (Yarn.Compiler, Google.Protobuf, CsvHelper) flow in
560	    /// transitively from MonoDreams.
561	    private static YarnProgram CompileYarn(string source)
562	    {
563	        var job = CompilationJob.CreateFromString("DemoDialogue", source);
564	        var result = Compiler.Compile(job);
565	        if (result.Program == null)
566	            throw new InvalidOperationException(
567	                "Demo Yarn script failed to compile: " + string.Join("; ", result.Diagnostics));
568	
569	        var program = new YarnProgram();
570	
571	        using (var memoryStream = new MemoryStream())
572	        using (var outputStream = new CodedOutputStream(memoryStream))
573	        {
574	            result.Program.WriteTo(outputStream);
575	            outputStream.Flush();
576	            program.CompiledProgram = memoryStream.ToArray();
577	        }
578	
579	        using (var memoryStream = new MemoryStream())
580	        {
581	            using var textWriter = new StreamWriter(memoryStream);
582	            var csv = new CsvWriter(textWriter, new CsvConfiguration(CultureInfo.InvariantCulture));
583	            var lines = result.StringTable!.Select(x => new
584	            {
585	                id = x.Key,
586	                text = x.Value.text,
587	                file = x.Value.fileName,
588	                node = x.Value.nodeName,
589	                lineNumber = x.Value.lineNumber,
590	            });
591	            csv.WriteRecords(lines);
592	            textWriter.Flush();
593	            memoryStream.Position = 0;
594	            using var reader = new StreamReader(memoryStream);
595	            program.BaseLocalizationId = CultureInfo.CurrentCulture.Name;
596	            program.BaseLocalisationStringTable = reader.ReadToEnd();
597	            program.Localizations = new YarnTranslation[0];
598	        }
599	
600	        return program;
601	    }
602	}
