611	/// WASD/arrow movement for the tagged player (a mesh shape, feet at the transform), clamped so
612	/// the body stays inside the boundary. Frozen while a dialogue is active.
613	[With(typeof(PlayerTag), typeof(TransformComponent))]
614	public sealed class PlayerMovementSystem : AEntitySetSystem<GameState>
615	{
616	    private readonly float _halfWidth;
617	    private readonly float _halfHeight;
618	    private readonly float _speed;
619	    private readonly float _clampHalfWidth;
620	    private readonly float _clampHeight;
621	    private readonly Func<bool> _isFrozen;
622	
623	    public PlayerMovementSystem(World world, float halfWidth, float halfHeight, float speed,
624	        float clampHalfWidth, float clampHeight, Func<bool> isFrozen)
625	        : base(world)
626	    {
627	        _halfWidth = halfWidth;
628	        _halfHeight = halfHeight;
629	        _speed = speed;
630	        _clampHalfWidth = clampHalfWidth;
631	        _clampHeight = clampHeight;
632	        _isFrozen = isFrozen;
633	    }
634	
635	    protected override void Update(GameState state, in Entity entity)
636	    {
637	        if (_isFrozen()) return;
638	
639	        var keyboard = Keyboard.GetState();
640	        var dir = Vector2.Zero;
641	        if (keyboard.IsKeyDown(Keys.A) || keyboard.IsKeyDown(Keys.Left)) dir.X -= 1f;
642	        if (keyboard.IsKeyDown(Keys.D) || keyboard.IsKeyDown(Keys.Right)) dir.X += 1f;
643	        if (keyboard.IsKeyDown(Keys.W) || keyboard.IsKeyDown(Keys.Up)) dir.Y -= 1f;
644	        if (keyboard.IsKeyDown(Keys.S) || keyboard.IsKeyDown(Keys.Down)) dir.Y += 1f;
645	
646	        if (dir == Vector2.Zero) return;
647	
648	        dir.Normalize();
649	        var transform = entity.Get<TransformComponent>();
650	        var next = transform.Position + dir * _speed * state.Time;
651	        // Feet anchored at the position; keep the whole body (which rises _clampHeight above the
652	        // feet) inside the boundary.
653	        next.X = MathHelper.Clamp(next.X, -_halfWidth + _clampHalfWidth, _halfWidth - _clampHalfWidth);
654	        next.Y = MathHelper.Clamp(next.Y, -_halfHeight + _clampHeight, _halfHeight);
655	        transform.Position = next;
656	    }
657	}
