659	/// One interactable NPC for <see cref="NpcInteractionSystem"/>: the character entity, its
660	/// above-head prompt, and the Yarn node its <see cref="DialogueStartMessage"/> kicks off.
661	public readonly record struct NpcInteractionTarget(Entity Npc, Entity Prompt, string StartNode);
662	
663	/// Shows a "press E" prompt when the player is near any NPC and, on the interact edge, publishes a
664	/// <see cref="DialogueStartMessage"/> for the nearest in-range one (node-ownership routing then
665	/// delivers it to the right DialogueSystem). Suppressed while any dialogue is active.
666	public sealed class NpcInteractionSystem : ISystem<GameState>
667	{
668	    private readonly Entity _player;
669	    private readonly NpcInteractionTarget[] _targets;
670	    private readonly AInputState _interact;
671	    private readonly float _rangeSq;
672	    private readonly Func<bool> _dialogueActive;
673	    private readonly World _world;
674	
675	    public bool IsEnabled { get; set; } = true;
676	
677	    public NpcInteractionSystem(World world, Entity player, NpcInteractionTarget[] targets,
678	        AInputState interact, float range, Func<bool> dialogueActive)
679	    {
680	        _world = world;
681	        _player = player;
682	        _targets = targets;
683	        _interact = interact;
684	        _rangeSq = range * range;
685	        _dialogueActive = dialogueActive;
686	    }
687	
688	    public void Update(GameState state)
689	    {
690	        if (!IsEnabled || !_player.IsAlive) return;
691	
692	        if (_dialogueActive())
693	        {
694	            foreach (var t in _targets) SetPromptVisible(t.Prompt, false);
695	            return;
696	        }
697	
698	        var playerPos = _player.Get<TransformComponent>().Position;
699	        var bestDistSq = _rangeSq;
700	        NpcInteractionTarget? nearest = null;
701	
702	        foreach (var t in _targets)
703	        {
704	            if (!t.Npc.IsAlive) { SetPromptVisible(t.Prompt, false); continue; }
705	            var distSq = Vector2.DistanceSquared(playerPos, t.Npc.Get<TransformComponent>().Position);
706	            var inRange = distSq <= _rangeSq;
707	            SetPromptVisible(t.Prompt, inRange);
708	            if (inRange && distSq <= bestDistSq) { bestDistSq = distSq; nearest = t; }
709	        }
710	
711	        if (nearest is { } target && _interact.JustPressed())
712	            _world.Publish(new DialogueStartMessage(target.Npc, target.StartNode));
713	    }
714	
715	    private static void SetPromptVisible(Entity prompt, bool visible)
716	    {
717	        if (!prompt.IsAlive) return;
718	        var has = prompt.Has<VisibleComponent>();
719	        if (visible && !has) prompt.Set<VisibleComponent>();
720	        else if (!visible && has) prompt.Remove<VisibleComponent>();
721	    }
722	
723	    public void Dispose() => GC.SuppressFinalize(this);
724	}
