730	/// Above-head reaction marks. Subscribes to <see cref="DialogueCommandMessage"/>, reacts to
731	/// `react who mark` by showing a generated mesh glyph above the keyed character (`player`, `npc`,
732	/// `bird`, …) on the Main target, and auto-hides it after a delay. Clears on dialogue end.
733	public sealed class ReactionMarkSystem : ISystem<GameState>
734	{
735	    private readonly Dictionary<string, Entity> _marks;
736	    private readonly float _duration;
737	    private readonly float _markSize;
738	
739	    public bool IsEnabled { get; set; } = true;
740	
741	    public ReactionMarkSystem(World world, Dictionary<string, Entity> marks,
742	        float duration, float markSize)
743	    {
744	        _marks = marks;
745	        _duration = duration;
746	        _markSize = markSize;
747	        world.Subscribe(this);
748	    }
749	
750	    [Subscribe]
751	    private void OnCommand(in DialogueCommandMessage msg)
752	    {
753	        var parts = msg.Command.Split(' ', StringSplitOptions.RemoveEmptyEntries);
754	        if (parts.Length < 3 || parts[0] != "react") return;
755	
756	        if (!_marks.TryGetValue(parts[1], out var target) || !target.IsAlive) return;
757	
758	        target.Set(new EmoteBubbleComponent { HideAt = float.NaN });
759	        if (!target.Has<VisibleComponent>()) target.Set<VisibleComponent>();
760	        target.Get<DrawComponent>().SetMeshData(DialogueGlyphs.ReactionMark(_markSize, parts[2]));
761	    }
762	
763	    [Subscribe]
764	    private void OnDialogueActive(in DialogueActiveMessage msg)
765	    {
766	        if (!msg.IsActive)
767	            foreach (var mark in _marks.Values) Hide(mark);
768	    }
769	
770	    public void Update(GameState state)
771	    {
772	        foreach (var mark in _marks.Values) Expire(mark, state.TotalTime);
773	    }
774	
775	    private void Expire(Entity mark, float now)
776	    {
777	        if (!mark.IsAlive || !mark.Has<EmoteBubbleComponent>()) return;
778	        ref var bubble = ref mark.Get<EmoteBubbleComponent>();
779	        if (float.IsNaN(bubble.HideAt)) { bubble.HideAt = now + _duration; return; }
780	        if (now >= bubble.HideAt) Hide(mark);
781	    }
782	
783	    // Main-target child — removing VisibleComponent is enough to hide it.
784	    private static void Hide(Entity mark)
785	    {
786	        if (!mark.IsAlive) return;
787	        if (mark.Has<VisibleComponent>()) mark.Remove<VisibleComponent>();
788	        if (mark.Has<EmoteBubbleComponent>()) mark.Remove<EmoteBubbleComponent>();
789	    }
790	
791	    public void Dispose() => GC.SuppressFinalize(this);
792	}
