794	/// In-box speaker portrait. Subscribes to <see cref="DialogueCommandMessage"/>; on
795	/// `emote who kind` it shows the framed mesh portrait of whoever is speaking in the single emote
796	/// frame (the box's left gutter). The NPC uses a cow-face glyph (`kind` ignored); the player
797	/// picks an emote-face glyph by `kind`. The portrait persists until the next `emote` or the
798	/// dialogue ends — it does not auto-expire (unlike reaction marks). Frame + face live on the UI
799	/// target, which always renders, so hiding empties the meshes rather than toggling VisibleComponent.
800	public sealed class DialoguePortraitSystem : ISystem<GameState>
801	{
802	    private readonly PortraitSlot _slot;
803	    private readonly MeshData _frameMesh;   // the static frame panel (shown on any emote)
804	    private readonly float _faceSize;
805	
806	    public bool IsEnabled { get; set; } = true;
807	
808	    public DialoguePortraitSystem(World world, PortraitSlot slot, float frameSize, float faceSize)
809	    {
810	        _slot = slot;
811	        _faceSize = faceSize;
812	        _frameMesh = ShapeBuilder.Panel(
813	            new Rectangle(0, 0, (int)frameSize, (int)frameSize), Color.Black, Color.White, 2f).Generate();
814	        world.Subscribe(this);
815	    }
816	
817	    [Subscribe]
818	    private void OnCommand(in DialogueCommandMessage msg)
819	    {
820	        var parts = msg.Command.Split(' ', StringSplitOptions.RemoveEmptyEntries);
821	        if (parts.Length < 3 || parts[0] != "emote") return;
822	
823	        switch (parts[1])
824	        {
825	            case "npc":
826	                ShowFace(DialogueGlyphs.CowFace(_faceSize).Generate()); // cow face, regardless of kind
827	                break;
828	            case "player":
829	                ShowFace(DialogueGlyphs.EmoteFace(_faceSize, parts[2]).Generate());
830	                break;
831	        }
832	    }
833	
834	    [Subscribe]
835	    private void OnDialogueActive(in DialogueActiveMessage msg)
836	    {
837	        if (!msg.IsActive)
838	        {
839	            ClearMesh(_slot.Frame);
840	            ClearMesh(_slot.Face);
841	        }
842	    }
843	
844	    public void Update(GameState state) { }
845	
846	    private void ShowFace(MeshData faceMesh)
847	    {
848	        // Show the (static) frame on the first emote, then swap in the speaker's face glyph.
849	        if (_slot.Frame.IsAlive) _slot.Frame.Get<DrawComponent>().SetMeshData(_frameMesh);
850	        if (_slot.Face.IsAlive) _slot.Face.Get<DrawComponent>().SetMeshData(faceMesh);
851	    }
852	
853	    private static void ClearMesh(Entity e)
854	    {
855	        if (!e.IsAlive || !e.Has<DrawComponent>()) return;
856	        ref var draw = ref e.Get<DrawComponent>();
857	        draw.Type = DrawElementType.Mesh;
858	        draw.Vertices = [];
859	        draw.Indices = [];
860	    }
861	
862	    public void Dispose() => GC.SuppressFinalize(this);
863	}
864	
865	/// Maps keyboard keys to the dialogue's interact/up/down <see cref="AInputState"/>s, updating
866	/// them once per frame so DialogueSystem and NpcInteractionSystem see fresh edges.
867	public sealed class DialogueDemoInputSystem : AKeyboardInputHandlingSystem
868	{
869	    public override List<(AInputState inputState, Keys)> InputMapping { get; }
870	
871	    public DialogueDemoInputSystem(AInputState interact, AInputState up, AInputState down)
872	    {
873	        InputMapping = new List<(AInputState inputState, Keys)>
874	        {
875	            (interact, Keys.E),
876	            (up, Keys.Up),
877	            (down, Keys.Down),
878	        };
879	    }
880	}
881	
882	/// Edge-triggered screen shortcuts: R resets the player, Escape returns to the launcher.
883	public sealed class DialogueDemoShortcutSystem : ISystem<GameState>
884	{
885	    private readonly DialogueDemoScreen _screen;
886	    private KeyboardState _previous;
887	    public bool IsEnabled { get; set; } = true;
888	
889	    public DialogueDemoShortcutSystem(DialogueDemoScreen screen)
890	    {
891	        _screen = screen;
892	        _previous = Keyboard.GetState();
893	    }
894	
895	    public void Update(GameState state)
896	    {
897	        if (!IsEnabled) return;
898	        var current = Keyboard.GetState();
899	        bool Pressed(Keys k) => current.IsKeyDown(k) && !_previous.IsKeyDown(k);
900	
901	        if (Pressed(Keys.R)) _screen.ResetPlayer();
902	        if (Pressed(Keys.Escape)) _screen.GoBackToLauncher();
903	
904	        _previous = current;
905	    }
906	
907	    public void Dispose() => GC.SuppressFinalize(this);
908	}
