913	/// Generated mesh glyphs for the dialogue scene — replaces the Sprout Lands character /
914	/// emote / icon sprites. World shapes are authored with the character's feet at the local
915	/// origin (body rising toward -Y); portrait faces fill a (0..size) box; reaction marks are
916	/// centred on the local origin.
917	internal static class DialogueGlyphs
918	{
919	    private static readonly Color Ink    = new(28, 30, 38);     // outlines, eyes, details
920	    private static readonly Color Player = new(86, 160, 196);   // player body
921	    private static readonly Color Cow    = new(224, 226, 230);  // cow body
922	    private static readonly Color Snout  = new(232, 160, 176);  // cow snout (pink)
