929	        new CompositeMeshGenerator()
930	            .Add(new CircleMeshGenerator(new Vector2(0, -r), r, Player, 28))
931	            .Add(new CircleOutlineMeshGenerator(new Vector2(0, -r), r, 2.5f, Ink, 28))
932	            .Add(new CircleMeshGenerator(new Vector2(-0.30f * r, -1.4f * r), 0.12f * r, Ink, 10))
933	            .Add(new CircleMeshGenerator(new Vector2(0.30f * r, -1.4f * r), 0.12f * r, Ink, 10));
934	
935	    /// World cow: a larger pale body with horns, a pink snout and eyes, feet at the origin.
936	    public static IMeshGenerator CowShape(float r) =>
937	        new CompositeMeshGenerator()
938	            .Add(new CircleMeshGenerator(new Vector2(0, -r), r, Cow, 28))
939	            .Add(new CircleOutlineMeshGenerator(new Vector2(0, -r), r, 2.5f, Ink, 28))
940	            .Add(new FilledTriangleMeshGenerator(
941	                new Vector2(-0.75f * r, -1.6f * r), new Vector2(-0.40f * r, -1.7f * r), new Vector2(-0.58f * r, -2.05f * r), Ink))
942	            .Add(new FilledTriangleMeshGenerator(
943	                new Vector2(0.75f * r, -1.6f * r), new Vector2(0.40f * r, -1.7f * r), new Vector2(0.58f * r, -2.05f * r), Ink))
944	            .Add(new CircleMeshGenerator(new Vector2(0, -0.55f * r), 0.40f * r, Snout, 18))
945	            .Add(new CircleOutlineMeshGenerator(new Vector2(0, -0.55f * r), 0.40f * r, 2f, Ink, 18))
