947	            .Add(new CircleMeshGenerator(new Vector2(0.35f * r, -1.35f * r), 0.11f * r, Ink, 10));
948	
949	    /// World bird: a small round body with a head, an orange beak (facing right) and an eye,
950	    /// feet at the origin. The upper-right NPC whose dialogue floats above its head.
951	    public static IMeshGenerator BirdShape(float r) =>
952	        new CompositeMeshGenerator()
953	            .Add(new CircleMeshGenerator(new Vector2(0, -r), r, Bird, 26))                          // body
954	            .Add(new CircleOutlineMeshGenerator(new Vector2(0, -r), r, 2.5f, Ink, 26))
955	            .Add(new CircleMeshGenerator(new Vector2(0, -1.85f * r), 0.62f * r, Bird, 24))          // head
956	            .Add(new CircleOutlineMeshGenerator(new Vector2(0, -1.85f * r), 0.62f * r, 2.5f, Ink, 24))
957	            .Add(new FilledTriangleMeshGenerator(                                                   // beak (points right)
958	                new Vector2(0.55f * r, -1.92f * r), new Vector2(1.02f * r, -1.78f * r), new Vector2(0.55f * r, -1.64f * r), Beak))
959	            .Add(new CircleMeshGenerator(new Vector2(0.20f * r, -2.02f * r), 0.10f * r, Ink, 10))   // eye
960	            .Add(new FilledTriangleMeshGenerator(                                                   // little wing
961	                new Vector2(-0.20f * r, -0.95f * r), new Vector2(-0.95f * r, -1.15f * r), new Vector2(-0.30f * r, -1.55f * r), new Color(226, 176, 78)));
962	
963	    /// Player emote face glyph: a head with eyes and a mouth keyed by <paramref name="kind"/>.
964	    public static IMeshGenerator EmoteFace(float s, string kind)
965	    {
966	        var c = new Vector2(s / 2f, s / 2f);
967	        var face = new CompositeMeshGenerator()
968	            .Add(new CircleMeshGenerator(c, 0.40f * s, Skin, 24))
969	            .Add(new CircleOutlineMeshGenerator(c, 0.40f * s, 2f, Ink, 24))
970	            .Add(new CircleMeshGenerator(c + new Vector2(-0.16f * s, -0.05f * s), 0.045f * s, Ink, 10))
971	            .Add(new CircleMeshGenerator(c + new Vector2(0.16f * s, -0.05f * s), 0.045f * s, Ink, 10));
972	
973	        switch (kind)
974	        {
