977	                {
978	                    c + new Vector2(-0.16f * s, 0.18f * s), c + new Vector2(0, 0.10f * s), c + new Vector2(0.16f * s, 0.18f * s),
979	                }, 2.5f, Ink));
980	                break;
981	            case "surprised":
982	                face.Add(new CircleOutlineMeshGenerator(c + new Vector2(0, 0.13f * s), 0.06f * s, 2f, Ink, 12));
983	                break;
984	            case "question":
985	                face.Add(new PolylineMeshGenerator(new[]
986	                {
