991	                face.Add(new PolylineMeshGenerator(new[]
992	                {
993	                    c + new Vector2(-0.16f * s, 0.10f * s), c + new Vector2(0, 0.18f * s), c + new Vector2(0.16f * s, 0.10f * s),
994	                }, 2.5f, Ink));
995	                break;
996	        }
997	        return face;
998	    }
999	
