1001	    public static IMeshGenerator CowFace(float s)
1002	    {
1003	        var c = new Vector2(s / 2f, s / 2f);
1004	        return new CompositeMeshGenerator()
1005	            .Add(new CircleMeshGenerator(c, 0.40f * s, Cow, 24))
1006	            .Add(new CircleOutlineMeshGenerator(c, 0.40f * s, 2f, Ink, 24))
1007	            .Add(new FilledTriangleMeshGenerator(
1008	                c + new Vector2(-0.34f * s, -0.20f * s), c + new Vector2(-0.16f * s, -0.26f * s), c + new Vector2(-0.26f * s, -0.42f * s), Ink))
1009	            .Add(new FilledTriangleMeshGenerator(
1010	                c + new Vector2(0.34f * s, -0.20f * s), c + new Vector2(0.16f * s, -0.26f * s), c + new Vector2(0.26f * s, -0.42f * s), Ink))
