1012	            .Add(new CircleOutlineMeshGenerator(c + new Vector2(0, 0.16f * s), 0.16f * s, 1.5f, Ink, 16))
1013	            .Add(new CircleMeshGenerator(c + new Vector2(-0.16f * s, -0.05f * s), 0.045f * s, Ink, 10))
1014	            .Add(new CircleMeshGenerator(c + new Vector2(0.16f * s, -0.05f * s), 0.045f * s, Ink, 10));
1015	    }
1016	
1017	    /// An above-head reaction mark centred on the local origin: exclaim "!", star, or "?".
1018	    public static IMeshGenerator ReactionMark(float s, string mark)
1019	    {
1020	        switch (mark)
1021	        {
