185	public static partial class DemoUIRowExtensions
186	{
187	    /// Composite "number box + label" row. The box is a <see cref="SimpleButtonComponent"/>
188	    /// (border + fill + hit-test) carrying a <see cref="TextInputComponent"/>; clicking it
189	    /// is dispatched as a <see cref="DemoButtonClicked"/> so the screen can focus it, and
190	    /// <c>TextInputSystem</c> edits the value while focused. Returns the box/input entity
191	    /// as <c>Outline</c> — set its focus and read its <c>TextInputComponent.Text</c> there.
192	    public static (Entity Container, Entity Outline, Vector2 Size) CreateNumberInputRow(
193	        this World world,
194	        string id,
195	        string rowLabel,
196	        string initialValue,
197	        int maxLength,
198	        BitmapFont font,
199	        NumberInputStyle style,
200	        float layerDepth,
201	        RenderTargetID target = RenderTargetID.HUD)
202	    {
