/// Concrete <see cref="AInputState"/> for the dialogue demo's per-action input.
public sealed class DemoInputState : AInputState { }

/// TEMP verification driver — REMOVE. Triggers the bird conversation and pulses the interact
/// edge so a headless run advances into the options phase for a screenshot.
public sealed class __TempBirdDriver : ISystem<GameState>
{
    private readonly World _world;
    private readonly Entity _bird;
    private readonly AInputState _interact;
    private int _frame;
    public bool IsEnabled { get; set; } = true;
    public __TempBirdDriver(World world, Entity bird, AInputState interact)
    {
        _world = world; _bird = bird; _interact = interact;
    }
    public void Update(GameState state)
    {
        _frame++;
        if (_frame == 15) _world.Publish(new DialogueStartMessage(_bird, "Bird"));
        if (_frame >= 30 && _frame % 22 == 0) _interact.Update(true, state); // pulse press to advance
    }
    public void Dispose() => GC.SuppressFinalize(this);
}

